// Курс Python — СОБРАН АВТОМАТИЧЕСКИ из course/u*.js (node scripts/build-course.js). Не править вручную.
(function (root) {
  const UNITS = {"units":[{"id":"u1","title":"Раздел 1. Первые шаги","lessons":[{"id":"l1","title":"Привет, print!","emoji":"👋","intro":"Команда <code>print()</code> выводит на экран то, что написано в скобках. Текст пишут в кавычках.","questions":[{"type":"choice","q":"Какая команда выводит текст на экран?","options":["print(\"Привет\")","say(\"Привет\")","echo \"Привет\"","write(Привет)"],"explain":"В Python текст выводит print(), а сам текст пишут в кавычках."},{"type":"output","q":"Что выведет код?","code":"print(\"Я учу Python\")","options":["Я учу Python","\"Я учу Python\"","print","Ошибку"],"explain":"Кавычки только показывают Python, где текст. На экран они не выводятся."},{"type":"bug","q":"Где ошибка?","code":"print(\"Привет)","options":["Нет закрывающей кавычки","Не хватает точки с запятой","print надо писать с большой буквы","Ошибки нет"],"explain":"Текст должен быть в кавычках с двух сторон: \"Привет\"."},{"type":"input","q":"Допиши код, чтобы на экран вывелось слово Питоша. Напиши только пропущенное слово.","code":"___(\"Питоша\")","answers":["print"],"explain":"print(\"Питоша\") выведет: Питоша"},{"type":"output","q":"Что выведет код?","code":"print(2 + 3)","options":["5","2 + 3","23","Ошибку"],"explain":"Без кавычек 2 + 3 — это пример, и Python его посчитал."},{"type":"output","q":"А этот код?","code":"print(\"2 + 3\")","options":["2 + 3","5","23","Ошибку"],"explain":"В кавычках — это просто текст, Python выводит его как есть."}]},{"id":"l2","title":"Числа и математика","emoji":"🔢","intro":"Python умеет считать: <code>+</code> <code>-</code> <code>*</code> (умножить) <code>/</code> (разделить), <code>//</code> (деление без остатка), <code>%</code> (остаток) и <code>**</code> (степень).","questions":[{"type":"output","q":"Что выведет код?","code":"print(10 - 4)","options":["6","14","10 - 4","-6"],"explain":"10 − 4 = 6."},{"type":"output","q":"Звёздочка * — это умножение. Что выведет код?","code":"print(3 * 4)","options":["12","34","7","3 * 4"],"explain":"3 × 4 = 12."},{"type":"output","q":"Что выведет код?","code":"print(7 / 2)","options":["3.5","3","3,5","4"],"explain":"Обычное деление даёт дробь. В Python дробную часть отделяют точкой: 3.5."},{"type":"output","q":"Две косые черты // — деление без остатка. Что выведет код?","code":"print(7 // 2)","options":["3","3.5","4","1"],"explain":"7 // 2 = 3: в 7 помещается три двойки, остаток отбрасывается."},{"type":"output","q":"Знак % даёт остаток от деления. Что выведет код?","code":"print(7 % 2)","options":["1","3","3.5","0"],"explain":"7 = 2 × 3 + 1, остаток — 1. Так проверяют, чётное ли число."},{"type":"output","q":"Две звёздочки ** — это степень. Что выведет код?","code":"print(2 ** 3)","options":["8","6","9","23"],"explain":"2 ** 3 = 2 × 2 × 2 = 8."},{"type":"input","q":"Напиши, что выведет код. Помни: сначала умножение, потом сложение.","code":"print(5 + 5 * 2)","answers":["15"],"explain":"Сначала 5 * 2 = 10, потом 5 + 10 = 15 — как в математике."}]},{"id":"l3","title":"Переменные","emoji":"📦","intro":"Переменная — это коробка с именем, в которую кладут значение: <code>age = 12</code>. Потом его можно достать по имени.","questions":[{"type":"choice","q":"Что делает знак = в строке name = \"Душка\"?","options":["Кладёт значение в переменную","Сравнивает два значения","Выводит текст на экран","Удаляет переменную"],"explain":"В Python = — это «положить в коробку». Теперь в name лежит \"Душка\"."},{"type":"output","q":"Что выведет код?","code":"age = 12\nprint(age)","options":["12","age","\"age\"","Ошибку"],"explain":"print(age) без кавычек достаёт то, что лежит в переменной age."},{"type":"output","q":"Что выведет код?","code":"x = 5\nx = x + 1\nprint(x)","options":["6","5","x + 1","51"],"explain":"Берём старое значение x (5), прибавляем 1 и кладём обратно. Теперь x = 6."},{"type":"bug","q":"Где ошибка?","code":"1name = \"Питоша\"","options":["Имя переменной не может начинаться с цифры","Нельзя писать текст в кавычках","Нужно добавить print","Ошибки нет"],"explain":"Имя может содержать цифры, но не может с них начинаться: name1 — можно, 1name — нельзя."},{"type":"output","q":"Что выведет код?","code":"a = 3\nb = 4\nprint(a * b)","options":["12","7","a * b","34"],"explain":"a * b = 3 × 4 = 12."},{"type":"input","q":"Допиши код, чтобы вывести название станицы. Напиши только пропущенное.","code":"city = \"Выселки\"\nprint(___)","answers":["city"],"explain":"print(city) выведет: Выселки. Без кавычек — потому что это имя переменной."}]},{"id":"l4","title":"Строки","emoji":"🔤","intro":"Строка — это текст в кавычках. Строки можно склеивать знаком <code>+</code>, повторять знаком <code>*</code> и узнавать длину через <code>len()</code>.","questions":[{"type":"output","q":"Что выведет код?","code":"print(\"Py\" + \"thon\")","options":["Python","Py thon","Py+thon","Ошибку"],"explain":"Плюс склеивает строки вплотную, без пробела."},{"type":"output","q":"Что выведет код?","code":"print(\"ха\" * 3)","options":["хахаха","ха3","ха ха ха","Ошибку"],"explain":"Строку можно умножить на число — она повторится столько раз."},{"type":"output","q":"len() считает символы. Что выведет код?","code":"name = \"Питоша\"\nprint(len(name))","options":["6","5","7","Питоша"],"explain":"П-и-т-о-ш-а — 6 букв."},{"type":"bug","q":"Почему этот код упадёт с ошибкой?","code":"print(\"Мне \" + 12 + \" лет\")","options":["Нельзя склеивать строку и число","Нельзя ставить пробелы в кавычках","Слишком много плюсов","Он не упадёт"],"explain":"Строку можно склеить только со строкой. Правильно: \"Мне \" + str(12) + \" лет\"."},{"type":"output","q":"Метод upper() делает буквы большими. Что выведет код?","code":"word = \"кот\"\nprint(word.upper())","options":["КОТ","кот","Кот","upper"],"explain":"upper() — все буквы заглавные, lower() — все маленькие."},{"type":"input","q":"Что выведет код? Напиши ответ.","code":"print(\"По\" * 2 + \"!\")","answers":["ПоПо!"],"explain":"Сначала \"По\" * 2 = \"ПоПо\", потом + \"!\" = \"ПоПо!\"."}]},{"id":"l5","title":"input и f-строки","emoji":"💬","intro":"<code>input()</code> ждёт, пока человек что-то напишет. А f-строка вставляет переменные прямо в текст: <code>f\"Привет, {name}!\"</code>.","questions":[{"type":"choice","q":"Что делает input()?","options":["Ждёт, пока человек что-то введёт","Выводит текст на экран","Считает пример","Удаляет переменную"],"explain":"input() останавливает программу и ждёт, что напишет человек."},{"type":"choice","q":"Человек ввёл 12. Что лежит в переменной age?","code":"age = input(\"Сколько тебе лет? \")","norun":true,"options":["Строка \"12\"","Число 12","Ничего","Ошибка"],"explain":"input() всегда возвращает строку. Чтобы получить число, пишут int(input())."},{"type":"output","q":"Что выведет код?","code":"x = int(\"5\")\nprint(x + 1)","options":["6","51","\"5\"1","Ошибку"],"explain":"int() превращает строку \"5\" в число 5, а 5 + 1 = 6."},{"type":"output","q":"Что выведет код?","code":"name = \"Ярик\"\nprint(f\"Привет, {name}!\")","options":["Привет, Ярик!","Привет, {name}!","Привет, name!","Ошибку"],"explain":"Буква f перед кавычками заставляет Python подставить значение в {скобки}."},{"type":"output","q":"Что выведет код?","code":"a = 2\nprint(f\"{a} + {a} = {a + a}\")","options":["2 + 2 = 4","{a} + {a} = {a + a}","a + a = 4","2 + 2 = 22"],"explain":"В {скобках} можно даже считать: {a + a} = 4."},{"type":"input","q":"Какую букву нужно поставить перед кавычками, чтобы подставилось значение score?","code":"score = 100\nprint(___\"Счёт: {score}\")","answers":["f"],"explain":"f\"Счёт: {score}\" выведет: Счёт: 100"}]},{"id":"p1a","title":"Практика: первые программы","emoji":"💻","intro":"Теперь пишешь код сам! Нажимай <b>▶️ Запустить</b>, чтобы посмотреть, что выйдет, и <b>Проверить</b> — чтобы Питоша прогнал тесты. Ошибаться можно сколько угодно — жизни тратятся, только если открыть решение.","questions":[{"type":"code","q":"Первая программа","task":"Напиши программу, которая выводит фразу: <code>Привет, Python!</code>","starter":"# напиши код здесь\n","tests":[{"out":"Привет, Python!"}],"hint":"Используй <code>print(\"...\")</code>. Текст — в кавычках.","solution":"print(\"Привет, Python!\")","explain":"print выводит на экран то, что в скобках."},{"type":"code","q":"Две строки","task":"Выведи две строки: сначала <code>Я учу Python</code>, а на следующей — <code>Мне нравится!</code>","starter":"","tests":[{"out":"Я учу Python\nМне нравится!"}],"hint":"Каждый print печатает новую строку. Нужно два print.","solution":"print(\"Я учу Python\")\nprint(\"Мне нравится!\")","explain":"Два print — две строки."},{"type":"code","q":"Калькулятор","task":"Выведи результат умножения <code>123 * 45</code> (само число, без текста).","starter":"","tests":[{"out":"5535"}],"hint":"Без кавычек Python посчитает: <code>print(123 * 45)</code>","solution":"print(123 * 45)","explain":"Python — отличный калькулятор."},{"type":"code","q":"Привет по имени","task":"Программа получает имя через <code>input()</code> и выводит <code>Привет, ИМЯ!</code><br>Например, для <code>Ира</code> → <code>Привет, Ира!</code>","starter":"name = input()\n","tests":[{"stdin":"Ира","out":"Привет, Ира!"},{"stdin":"Душка","out":"Привет, Душка!"}],"hint":"f-строка: <code>print(f\"Привет, {name}!\")</code>","solution":"name = input()\nprint(f\"Привет, {name}!\")","explain":"input() читает ввод, f-строка подставляет его в текст."}]},{"id":"p1b","title":"Практика: считаем с input","emoji":"🧮","intro":"<code>input()</code> всегда даёт строку. Чтобы считать, превращай её в число: <code>int(input())</code>.","questions":[{"type":"code","q":"Сумма двух чисел","task":"Прочитай два числа (каждое на своей строке) и выведи их сумму.","starter":"a = int(input())\n","tests":[{"stdin":"2\n3","out":"5"},{"stdin":"10\n-4","out":"6"},{"stdin":"0\n0","out":"0"}],"hint":"Прочитай второе число так же: <code>b = int(input())</code>, потом <code>print(a + b)</code>","solution":"a = int(input())\nb = int(input())\nprint(a + b)","explain":"Без int() получилось бы склеивание строк: \"2\" + \"3\" = \"23\"."},{"type":"code","q":"Через год","task":"Прочитай возраст и выведи <code>Через год тебе будет N</code>, где N — возраст + 1.","starter":"","tests":[{"stdin":"12","out":"Через год тебе будет 13"},{"stdin":"0","out":"Через год тебе будет 1"}],"hint":"<code>age = int(input())</code>, потом f-строка с <code>{age + 1}</code>","solution":"age = int(input())\nprint(f\"Через год тебе будет {age + 1}\")","explain":"Внутри {} в f-строке можно считать."},{"type":"code","q":"Площадь","task":"Прочитай длину и ширину прямоугольника (две строки) и выведи его площадь.","starter":"","tests":[{"stdin":"3\n4","out":"12"},{"stdin":"10\n10","out":"100"}],"hint":"Площадь = длина × ширина.","solution":"a = int(input())\nb = int(input())\nprint(a * b)","explain":"Это уже настоящая полезная программа!"},{"type":"code","q":"Минуты в секунды","task":"Прочитай число минут и выведи, сколько это секунд.","starter":"","tests":[{"stdin":"5","out":"300"},{"stdin":"0","out":"0"},{"stdin":"90","out":"5400"}],"hint":"В минуте 60 секунд.","solution":"m = int(input())\nprint(m * 60)","explain":"Перевод единиц — частая задача."}]}]},{"id":"u2","title":"Раздел 2. Условия","lessons":[{"id":"l6","title":"Правда или ложь","emoji":"⚖️","intro":"Сравнение даёт ответ <code>True</code> (правда) или <code>False</code> (ложь). Знаки: <code>==</code> равно, <code>!=</code> не равно, <code>&gt;</code> <code>&lt;</code> <code>&gt;=</code> <code>&lt;=</code>.","questions":[{"type":"output","q":"Что выведет код?","code":"print(5 > 3)","options":["True","False","5 > 3","Ошибку"],"explain":"5 больше 3 — это правда, поэтому True."},{"type":"output","q":"Что выведет код?","code":"print(2 == 3)","options":["False","True","2 == 3","Ошибку"],"explain":"== проверяет, равны ли числа. 2 не равно 3 — False."},{"type":"choice","q":"Чем отличаются = и ==?","options":["= кладёт значение в переменную, == сравнивает","Ничем, это одно и то же","== кладёт значение, = сравнивает","== — это ошибка в Python"],"explain":"Одно = — «положить в коробку», два == — «равны ли?». Путать их — самая частая ошибка новичков."},{"type":"output","q":"Знак != значит «не равно». Что выведет код?","code":"print(10 != 10)","options":["False","True","10","Ошибку"],"explain":"10 равно 10, значит утверждение «не равно» ложное — False."},{"type":"output","q":"Что выведет код?","code":"age = 12\nprint(age >= 12)","options":["True","False","12","Ошибку"],"explain":">= — «больше или равно». 12 равно 12, значит True."},{"type":"input","q":"Что выведет код? Напиши ответ.","code":"print(7 < 7)","answers":["False"],"explain":"7 не меньше 7 (они равны), поэтому False. А вот 7 <= 7 было бы True."}]},{"id":"l7","title":"if и else","emoji":"🔀","intro":"<code>if</code> выполняет код, только если условие верно. <code>else</code> — если неверно. После условия ставят двоеточие, а код внутри сдвигают на 4 пробела.","questions":[{"type":"output","q":"Что выведет код?","code":"x = 10\nif x > 5:\n    print(\"Много\")\nelse:\n    print(\"Мало\")","options":["Много","Мало","Много и Мало","Ничего"],"explain":"10 > 5 — правда, выполняется ветка if."},{"type":"output","q":"А если x = 3?","code":"x = 3\nif x > 5:\n    print(\"Много\")\nelse:\n    print(\"Мало\")","options":["Мало","Много","Ничего","Ошибку"],"explain":"3 > 5 — ложь, поэтому выполняется else."},{"type":"bug","q":"Где ошибка?","code":"x = 7\nif x > 5\n    print(\"Да\")","options":["Нет двоеточия после условия","Нужно писать If с большой буквы","Нельзя сравнивать с 5","Ошибки нет"],"explain":"После условия обязательно двоеточие: if x > 5:"},{"type":"bug","q":"Где ошибка?","code":"x = 7\nif x > 5:\nprint(\"Да\")","options":["Нет отступа перед print","Нет else","Лишнее двоеточие","Ошибки нет"],"explain":"Код внутри if сдвигают на 4 пробела. Так Python понимает, что относится к условию."},{"type":"output","q":"Что выведет код?","code":"score = 100\nif score == 100:\n    print(\"Идеально!\")\nprint(\"Конец\")","out":"Идеально!\nКонец","options":["Идеально! и потом Конец","Только Конец","Только Идеально!","Ошибку"],"explain":"print(\"Конец\") без отступа — он не внутри if и выполняется всегда."},{"type":"input","q":"Какое слово пропущено? (напиши только его)","code":"temp = 30\nif temp > 25:\n    print(\"Жарко\")\n___:\n    print(\"Прохладно\")","answers":["else"],"explain":"else — «иначе». Выполнится, если условие в if ложное."}]},{"id":"l8","title":"elif — много вариантов","emoji":"🪜","intro":"<code>elif</code> — «иначе если». Python проверяет условия сверху вниз и выполняет <b>только первую</b> подходящую ветку.","questions":[{"type":"output","q":"Что выведет код?","code":"n = 0\nif n > 0:\n    print(\"Плюс\")\nelif n < 0:\n    print(\"Минус\")\nelse:\n    print(\"Ноль\")","options":["Ноль","Плюс","Минус","Ничего"],"explain":"0 не больше и не меньше нуля — сработал else."},{"type":"output","q":"Что выведет код?","code":"grade = 4\nif grade == 5:\n    print(\"Отлично\")\nelif grade == 4:\n    print(\"Хорошо\")\nelse:\n    print(\"Надо подтянуть\")","options":["Хорошо","Отлично","Надо подтянуть","Хорошо и Надо подтянуть"],"explain":"Первое условие ложно, второе (grade == 4) — правда."},{"type":"choice","q":"Сколько веток elif можно написать?","options":["Сколько угодно","Только одну","Не больше трёх","Ни одной без else"],"explain":"elif можно повторять сколько нужно, а else в конце — по желанию."},{"type":"output","q":"Внимательно! Что выведет код?","code":"x = 15\nif x > 10:\n    print(\"A\")\nelif x > 5:\n    print(\"B\")","options":["A","B","A и B","Ничего"],"explain":"Хотя 15 > 5 тоже верно, Python остановился на первой подходящей ветке — A."},{"type":"output","q":"Что выведет код?","code":"t = 18\nif t < 0:\n    print(\"Мороз\")\nelif t < 15:\n    print(\"Прохладно\")\nelif t < 25:\n    print(\"Тепло\")\nelse:\n    print(\"Жара\")","options":["Тепло","Прохладно","Жара","Мороз"],"explain":"18 не меньше 0 и не меньше 15, но меньше 25 — «Тепло»."},{"type":"input","q":"Какое слово означает «иначе если»?","answers":["elif"],"explain":"elif = else + if."}]},{"id":"l9","title":"and, or, not","emoji":"🔗","intro":"<code>and</code> — правда, если верны оба условия. <code>or</code> — если верно хотя бы одно. <code>not</code> переворачивает: True ↔ False.","questions":[{"type":"output","q":"Что выведет код?","code":"print(True and False)","options":["False","True","TrueFalse","Ошибку"],"explain":"and требует, чтобы оба были True. Один False — значит False."},{"type":"output","q":"Что выведет код?","code":"print(True or False)","options":["True","False","TrueFalse","Ошибку"],"explain":"or достаточно одного True."},{"type":"output","q":"Что выведет код?","code":"print(not True)","options":["False","True","not True","Ошибку"],"explain":"not переворачивает значение."},{"type":"output","q":"Что выведет код?","code":"age = 12\nprint(age > 10 and age < 14)","options":["True","False","12","Ошибку"],"explain":"12 > 10 — да, 12 < 14 — да. Оба верны — True."},{"type":"output","q":"Что выведет код?","code":"day = \"суббота\"\nprint(day == \"суббота\" or day == \"воскресенье\")","options":["True","False","суббота","Ошибку"],"explain":"Первое условие верно, для or этого достаточно."},{"type":"input","q":"Что выведет код? Напиши ответ.","code":"print(5 > 3 and 2 > 4)","answers":["False"],"explain":"5 > 3 — правда, но 2 > 4 — ложь. С and получается False."}]},{"id":"l10","title":"Практика: условия","emoji":"🎯","intro":"Проверка чётности: число чётное, если <code>n % 2 == 0</code> (остаток от деления на 2 равен нулю). Условия можно вкладывать друг в друга.","questions":[{"type":"output","q":"Что выведет код?","code":"n = 7\nif n % 2 == 0:\n    print(\"Чётное\")\nelse:\n    print(\"Нечётное\")","options":["Нечётное","Чётное","1","Ошибку"],"explain":"7 % 2 = 1, не 0 — значит нечётное."},{"type":"output","q":"Что выведет код?","code":"x = 20\nif x % 5 == 0 and x % 2 == 0:\n    print(\"Делится на 10\")\nelse:\n    print(\"Нет\")","options":["Делится на 10","Нет","20","Ошибку"],"explain":"20 делится и на 5, и на 2 — значит и на 10."},{"type":"output","q":"Код выбирает большее число. Что выведет?","code":"a = 8\nb = 12\nif a > b:\n    print(a)\nelse:\n    print(b)","options":["12","8","20","a"],"explain":"8 > 12 — ложь, выполняется else и печатает b."},{"type":"bug","q":"Почему этот код не запустится?","code":"pas = \"123\"\nif pas = \"123\":\n    print(\"Вход\")","options":["В условии нужно ==, а не =","Пароль нельзя хранить в строке","Нужно писать else","Он запустится"],"explain":"Для сравнения — два знака ==. Одно = в условии — ошибка."},{"type":"output","q":"Условие внутри условия. Что выведет?","code":"x = 5\nif x > 3:\n    if x < 10:\n        print(\"От 3 до 10\")","options":["От 3 до 10","Ничего","Ошибку","x"],"explain":"Внешнее условие верно, внутреннее тоже — печатается текст."},{"type":"input","q":"Что выведет код? Напиши ответ.","code":"n = 9\nif n > 5:\n    n = n - 5\nprint(n)","answers":["4"],"explain":"9 > 5, поэтому n = 9 − 5 = 4."}]},{"id":"p2a","title":"Практика: условия","emoji":"💻","intro":"Пишем программы, которые принимают решения. Помни про двоеточие после условия и отступ в 4 пробела.","questions":[{"type":"code","q":"Чётное или нечётное","task":"Прочитай число и выведи <code>Чётное</code> или <code>Нечётное</code>.","starter":"n = int(input())\n","tests":[{"stdin":"4","out":"Чётное"},{"stdin":"7","out":"Нечётное"},{"stdin":"0","out":"Чётное"}],"hint":"Чётное, если <code>n % 2 == 0</code>.","solution":"n = int(input())\nif n % 2 == 0:\n    print(\"Чётное\")\nelse:\n    print(\"Нечётное\")","explain":"Остаток от деления на 2 — главный способ проверить чётность."},{"type":"code","q":"Большее из двух","task":"Прочитай два числа и выведи большее (если равны — любое из них).","starter":"","tests":[{"stdin":"3\n8","out":"8"},{"stdin":"10\n2","out":"10"},{"stdin":"5\n5","out":"5"}],"hint":"<code>if a > b:</code> печатай a, иначе — b.","solution":"a = int(input())\nb = int(input())\nif a > b:\n    print(a)\nelse:\n    print(b)","explain":"Можно было и короче: print(max(a, b))."},{"type":"code","q":"Знак числа","task":"Прочитай число и выведи <code>Положительное</code>, <code>Отрицательное</code> или <code>Ноль</code>.","starter":"","tests":[{"stdin":"5","out":"Положительное"},{"stdin":"-3","out":"Отрицательное"},{"stdin":"0","out":"Ноль"}],"hint":"Три варианта — значит if, elif и else.","solution":"n = int(input())\nif n > 0:\n    print(\"Положительное\")\nelif n < 0:\n    print(\"Отрицательное\")\nelse:\n    print(\"Ноль\")","explain":"elif — когда вариантов больше двух."},{"type":"code","q":"Доступ по возрасту","task":"Прочитай возраст. Если 12 или больше — выведи <code>Можно</code>, иначе — <code>Рано</code>.","starter":"","tests":[{"stdin":"12","out":"Можно"},{"stdin":"11","out":"Рано"},{"stdin":"30","out":"Можно"}],"hint":"«12 или больше» — это <code>>= 12</code>.","solution":"age = int(input())\nif age >= 12:\n    print(\"Можно\")\nelse:\n    print(\"Рано\")","explain":"Следи за границей: 12 должно пройти."}]},{"id":"p2b","title":"Практика: сложные условия","emoji":"🧠","intro":"Задачи посложнее: несколько веток, <code>and</code> и <code>or</code>.","questions":[{"type":"code","q":"Оценка за тест","task":"Прочитай баллы (0–100) и выведи оценку: 90 и выше — <code>5</code>, 75–89 — <code>4</code>, 50–74 — <code>3</code>, меньше 50 — <code>2</code>.","starter":"score = int(input())\n","tests":[{"stdin":"95","out":"5"},{"stdin":"90","out":"5"},{"stdin":"80","out":"4"},{"stdin":"75","out":"4"},{"stdin":"50","out":"3"},{"stdin":"10","out":"2"}],"hint":"Проверяй сверху вниз: <code>if score >= 90</code>, <code>elif score >= 75</code>…","solution":"score = int(input())\nif score >= 90:\n    print(5)\nelif score >= 75:\n    print(4)\nelif score >= 50:\n    print(3)\nelse:\n    print(2)","explain":"Порядок веток важен: сначала самое строгое условие."},{"type":"code","q":"Високосный год","task":"Год високосный, если делится на 4, но не на 100, <b>или</b> делится на 400. Прочитай год и выведи <code>Да</code> или <code>Нет</code>.","starter":"","tests":[{"stdin":"2024","out":"Да"},{"stdin":"1900","out":"Нет"},{"stdin":"2000","out":"Да"},{"stdin":"2023","out":"Нет"}],"hint":"<code>(y % 4 == 0 and y % 100 != 0) or y % 400 == 0</code>","solution":"y = int(input())\nif (y % 4 == 0 and y % 100 != 0) or y % 400 == 0:\n    print(\"Да\")\nelse:\n    print(\"Нет\")","explain":"Скобки помогают не запутаться в and и or."},{"type":"code","q":"Пароль","task":"Прочитай пароль. Если это <code>python123</code> — выведи <code>Доступ разрешён</code>, иначе <code>Неверный пароль</code>.","starter":"","tests":[{"stdin":"python123","out":"Доступ разрешён"},{"stdin":"qwerty","out":"Неверный пароль"},{"stdin":"Python123","out":"Неверный пароль"}],"hint":"Сравнивай строки через ==. Большие и маленькие буквы различаются!","solution":"p = input()\nif p == \"python123\":\n    print(\"Доступ разрешён\")\nelse:\n    print(\"Неверный пароль\")","explain":"Python различает регистр: «Python123» ≠ «python123»."},{"type":"code","q":"Наибольшее из трёх","task":"Прочитай три числа (каждое на своей строке) и выведи наибольшее. Попробуй без <code>max()</code>!","starter":"","tests":[{"stdin":"1\n5\n3","out":"5"},{"stdin":"-1\n-5\n-3","out":"-1"},{"stdin":"7\n7\n2","out":"7"},{"stdin":"1\n2\n9","out":"9"}],"hint":"Заведи <code>best = a</code>, потом сравни с b и c: <code>if b > best: best = b</code>.","solution":"a = int(input())\nb = int(input())\nc = int(input())\nbest = a\nif b > best:\n    best = b\nif c > best:\n    best = c\nprint(best)","explain":"Приём «лучший на данный момент» пригодится много раз."}]}]},{"id":"u3","title":"Раздел 3. Циклы","lessons":[{"id":"l11","title":"Цикл for и range","emoji":"🔁","intro":"<code>for i in range(5):</code> повторяет код 5 раз, а <code>i</code> по очереди равно 0, 1, 2, 3, 4. <code>range(a, b)</code> — от a до b, не включая b.","questions":[{"type":"output","q":"Что выведет код?","code":"for i in range(3):\n    print(\"Привет\")","out":"Привет\nПривет\nПривет","options":["Привет 3 раза","Привет 1 раз","Привет 4 раза","Ошибку"],"explain":"range(3) — три повтора: i = 0, 1, 2."},{"type":"output","q":"Что выведет код?","code":"for i in range(4):\n    print(i)","out":"0\n1\n2\n3","options":["0, 1, 2, 3 — каждое с новой строки","1, 2, 3, 4","0, 1, 2, 3, 4","4"],"explain":"Счёт начинается с 0, а 4 уже не входит."},{"type":"choice","q":"Какие числа даёт range(2, 6)?","options":["2, 3, 4, 5","2, 3, 4, 5, 6","3, 4, 5, 6","Только 2 и 6"],"explain":"Начало включается, конец — нет."},{"type":"output","q":"Третье число в range — это шаг. Что выведет код?","code":"for i in range(1, 10, 3):\n    print(i)","out":"1\n4\n7","options":["1, 4, 7","1, 3, 9","1, 4, 7, 10","3, 6, 9"],"explain":"Начинаем с 1 и прибавляем по 3: 1, 4, 7. 10 уже не входит."},{"type":"output","q":"Что выведет код?","code":"total = 0\nfor i in range(1, 5):\n    total = total + i\nprint(total)","options":["10","15","4","5"],"explain":"1 + 2 + 3 + 4 = 10. 5 не входит в range(1, 5)."},{"type":"choice","q":"Сколько раз напечатается «Да»?","code":"for i in range(5):\n    print(\"Да\")","nocheck":true,"options":["5","4","6","1"],"explain":"range(5) — ровно 5 повторов."}]},{"id":"l12","title":"Цикл while","emoji":"🔄","intro":"<code>while условие:</code> повторяет код, <b>пока</b> условие верно. Не забудь менять переменную, иначе цикл не остановится!","questions":[{"type":"output","q":"Что выведет код?","code":"n = 1\nwhile n < 4:\n    print(n)\n    n = n + 1","out":"1\n2\n3","options":["1, 2, 3","1, 2, 3, 4","0, 1, 2, 3","Бесконечно"],"explain":"Когда n стало 4, условие n < 4 ложно — цикл закончился."},{"type":"choice","q":"Что сделает код: while True: print(\"Ой\")?","options":["Будет печатать «Ой» бесконечно","Напечатает один раз","Выдаст ошибку","Ничего не сделает"],"explain":"True всегда правда — цикл никогда не кончится. Остановить можно через break."},{"type":"bug","q":"Что не так с этим циклом?","code":"n = 5\nwhile n > 0:\n    print(n)","norun":true,"noError":true,"options":["n не уменьшается — цикл бесконечный","Нельзя печатать n","Нет двоеточия","Всё правильно"],"explain":"Нужно добавить n = n - 1, иначе n всегда 5 и цикл не остановится."},{"type":"output","q":"Что выведет код?","code":"x = 10\nwhile x > 0:\n    x = x - 3\nprint(x)","options":["-2","1","0","10"],"explain":"10 → 7 → 4 → 1 → -2. Когда x = -2, условие x > 0 ложно."},{"type":"output","q":"Сколько раз можно поделить 100 пополам, пока не станет 1?","code":"count = 0\nn = 100\nwhile n > 1:\n    n = n // 2\n    count = count + 1\nprint(count)","options":["6","7","50","5"],"explain":"100 → 50 → 25 → 12 → 6 → 3 → 1: шесть шагов."},{"type":"input","q":"Какое слово начинает цикл «пока»?","answers":["while"],"explain":"while — «пока»."}]},{"id":"l13","title":"break и continue","emoji":"⏭️","intro":"<code>break</code> — сразу выйти из цикла. <code>continue</code> — пропустить остаток шага и перейти к следующему.","questions":[{"type":"output","q":"Что выведет код?","code":"for i in range(10):\n    if i == 3:\n        break\n    print(i)","out":"0\n1\n2","options":["0, 1, 2","0, 1, 2, 3","3","Все числа от 0 до 9"],"explain":"Когда i стало 3, break прервал цикл до print."},{"type":"output","q":"Что выведет код?","code":"for i in range(5):\n    if i == 2:\n        continue\n    print(i)","out":"0\n1\n3\n4","options":["0, 1, 3, 4","0, 1","2","0, 1, 2, 3, 4"],"explain":"continue пропустил печать только для i = 2."},{"type":"choice","q":"Что делает break?","options":["Сразу выходит из цикла","Пропускает один шаг","Начинает цикл заново","Выключает компьютер"],"explain":"break — «прервать»."},{"type":"choice","q":"Что делает continue?","options":["Пропускает остаток шага и идёт к следующему","Выходит из цикла","Повторяет шаг ещё раз","Ставит программу на паузу"],"explain":"continue — «продолжить со следующего шага»."},{"type":"output","q":"Что выведет код?","code":"n = 0\nwhile True:\n    n = n + 1\n    if n == 5:\n        break\nprint(n)","options":["5","4","Бесконечно","0"],"explain":"while True + break — частый приём: крутим, пока не выполнится условие."},{"type":"input","q":"Какое слово сразу выходит из цикла?","answers":["break"],"explain":"break."}]},{"id":"l14","title":"Счётчики и суммы","emoji":"➕","intro":"Запись <code>x += 2</code> — короткая форма <code>x = x + 2</code>. Так же работают <code>-=</code>, <code>*=</code>. Цикл <code>for</code> умеет идти и по буквам строки.","questions":[{"type":"output","q":"Что выведет код?","code":"s = 0\nfor x in range(1, 4):\n    s += x\nprint(s)","options":["6","10","3","4"],"explain":"1 + 2 + 3 = 6."},{"type":"output","q":"Код считает буквы «а». Что выведет?","code":"count = 0\nfor ch in \"банан\":\n    if ch == \"а\":\n        count += 1\nprint(count)","options":["2","1","3","5"],"explain":"б-а-н-а-н: две буквы «а»."},{"type":"output","q":"Что выведет код?","code":"p = 1\nfor i in range(1, 5):\n    p *= i\nprint(p)","options":["24","10","120","0"],"explain":"1 × 2 × 3 × 4 = 24."},{"type":"output","q":"Что выведет код?","code":"for ch in \"кот\":\n    print(ch)","out":"к\nо\nт","options":["к, о, т — каждая с новой строки","кот","к о т в одну строку","Ошибку"],"explain":"for проходит по строке буква за буквой."},{"type":"choice","q":"Что значит x += 2?","options":["x = x + 2","x = 2","x == 2","x = x * 2"],"explain":"Это сокращение, его пишут очень часто."},{"type":"input","q":"Что выведет код? Напиши ответ.","code":"s = 0\nfor i in range(5):\n    s += 2\nprint(s)","answers":["10"],"explain":"5 раз прибавили по 2 — получилось 10."}]},{"id":"l15","title":"Вложенные циклы","emoji":"🧩","intro":"Цикл можно положить внутрь цикла. А у <code>print</code> есть настройки: <code>end=\"\"</code> — не переходить на новую строку, <code>sep=\"-\"</code> — чем разделять значения.","questions":[{"type":"output","q":"Что выведет код?","code":"for i in range(2):\n    for j in range(3):\n        print(\"*\", end=\"\")\n    print()","out":"***\n***","options":["*** на двух строках","****** в одну строку","* на шести строках","Ошибку"],"explain":"Внутренний цикл печатает *** в строку, потом print() переводит строку. И так 2 раза."},{"type":"output","q":"Строку можно умножать. Что выведет код?","code":"for i in range(1, 4):\n    print(\"#\" * i)","out":"#\n##\n###","options":["Лесенку: #, ##, ###","### в одну строку","# # #","Ошибку"],"explain":"На каждом шаге решёток на одну больше."},{"type":"output","q":"Сколько раз выполнится внутренний код?","code":"count = 0\nfor i in range(3):\n    for j in range(4):\n        count += 1\nprint(count)","options":["12","7","3","4"],"explain":"3 раза по 4 = 12."},{"type":"output","q":"Что выведет код?","code":"print(\"a\", \"b\", sep=\"-\")","options":["a-b","a b","ab","a-b-"],"explain":"sep задаёт разделитель между значениями (обычно это пробел)."},{"type":"output","q":"Что выведет код?","code":"print(\"Привет\", end=\"!\")\nprint(\"Мир\")","options":["Привет!Мир","Привет! и Мир на новой строке","Привет Мир!","Привет!"],"explain":"end=\"!\" поставил «!» вместо перехода на новую строку."},{"type":"input","q":"Что выведет код? Напиши ответ (через пробел).","code":"for i in range(3):\n    print(i * i, end=\" \")","answers":["0 1 4"],"explain":"0×0 = 0, 1×1 = 1, 2×2 = 4, всё в одну строку."}]},{"id":"p3a","title":"Практика: циклы","emoji":"💻","intro":"Циклы на практике: считаем, повторяем, рисуем.","questions":[{"type":"code","q":"Считалка","task":"Прочитай число n и выведи числа от 1 до n, каждое с новой строки.","starter":"n = int(input())\n","tests":[{"stdin":"3","out":"1\n2\n3"},{"stdin":"1","out":"1"},{"stdin":"5","out":"1\n2\n3\n4\n5"}],"hint":"<code>for i in range(1, n + 1):</code>","solution":"n = int(input())\nfor i in range(1, n + 1):\n    print(i)","explain":"range(1, n + 1) — потому что конец не включается."},{"type":"code","q":"Сумма до n","task":"Прочитай n и выведи сумму чисел от 1 до n.","starter":"","tests":[{"stdin":"5","out":"15"},{"stdin":"100","out":"5050"},{"stdin":"1","out":"1"}],"hint":"Заведи <code>total = 0</code> и прибавляй в цикле.","solution":"n = int(input())\ntotal = 0\nfor i in range(1, n + 1):\n    total += i\nprint(total)","explain":"Накопление суммы — один из главных приёмов."},{"type":"code","q":"Таблица умножения","task":"Прочитай число n и выведи таблицу умножения на него от 1 до 10 в формате <code>n x i = результат</code>.<br>Например, первая строка для 2: <code>2 x 1 = 2</code>","starter":"","tests":[{"stdin":"2","out":"2 x 1 = 2\n2 x 2 = 4\n2 x 3 = 6\n2 x 4 = 8\n2 x 5 = 10\n2 x 6 = 12\n2 x 7 = 14\n2 x 8 = 16\n2 x 9 = 18\n2 x 10 = 20"},{"stdin":"7","out":"7 x 1 = 7\n7 x 2 = 14\n7 x 3 = 21\n7 x 4 = 28\n7 x 5 = 35\n7 x 6 = 42\n7 x 7 = 49\n7 x 8 = 56\n7 x 9 = 63\n7 x 10 = 70"}],"hint":"<code>print(f\"{n} x {i} = {n * i}\")</code> внутри цикла по i.","solution":"n = int(input())\nfor i in range(1, 11):\n    print(f\"{n} x {i} = {n * i}\")","explain":"f-строки + цикл = красивые таблицы."},{"type":"code","q":"Обратный отсчёт","task":"Прочитай n и выведи числа от n до 1 (каждое с новой строки), а потом <code>Пуск!</code>","starter":"","tests":[{"stdin":"3","out":"3\n2\n1\nПуск!"},{"stdin":"1","out":"1\nПуск!"}],"hint":"Можно <code>range(n, 0, -1)</code> или while с уменьшением.","solution":"n = int(input())\nfor i in range(n, 0, -1):\n    print(i)\nprint(\"Пуск!\")","explain":"Шаг -1 считает назад."}]},{"id":"p3b","title":"Практика: циклы посложнее","emoji":"🔥","intro":"Факториал, лесенки и цифры числа — классика для тренировки циклов.","questions":[{"type":"code","q":"Факториал","task":"Прочитай n и выведи n! = 1 × 2 × … × n. Учти: 0! = 1.","starter":"","tests":[{"stdin":"5","out":"120"},{"stdin":"0","out":"1"},{"stdin":"1","out":"1"},{"stdin":"10","out":"3628800"}],"hint":"Начни с <code>p = 1</code> и умножай в цикле.","solution":"n = int(input())\np = 1\nfor i in range(1, n + 1):\n    p *= i\nprint(p)","explain":"Для 0 цикл не выполнится ни разу, и останется 1 — то, что нужно."},{"type":"code","q":"Лесенка","task":"Прочитай n и нарисуй лесенку из звёздочек: в первой строке <code>*</code>, во второй <code>**</code> … в n-й — n звёздочек.","starter":"","tests":[{"stdin":"3","out":"*\n**\n***"},{"stdin":"1","out":"*"},{"stdin":"5","out":"*\n**\n***\n****\n*****"}],"hint":"Строку можно умножать: <code>\"*\" * i</code>.","solution":"n = int(input())\nfor i in range(1, n + 1):\n    print(\"*\" * i)","explain":"Умножение строки на число — очень удобный приём."},{"type":"code","q":"Сколько цифр","task":"Прочитай положительное число и выведи, сколько в нём цифр. Используй <code>while</code> и деление <code>//</code> (без len!).","starter":"","tests":[{"stdin":"12345","out":"5"},{"stdin":"7","out":"1"},{"stdin":"1000","out":"4"}],"hint":"Пока n > 0: <code>n = n // 10</code> и счётчик += 1.","solution":"n = int(input())\ncount = 0\nwhile n > 0:\n    n = n // 10\n    count += 1\nprint(count)","explain":"n // 10 «откусывает» последнюю цифру."},{"type":"code","q":"Сумма цифр","task":"Прочитай положительное число и выведи сумму его цифр.","starter":"","tests":[{"stdin":"123","out":"6"},{"stdin":"9","out":"9"},{"stdin":"1001","out":"2"}],"hint":"Последняя цифра — <code>n % 10</code>, потом <code>n = n // 10</code>.","solution":"n = int(input())\ns = 0\nwhile n > 0:\n    s += n % 10\n    n = n // 10\nprint(s)","explain":"% 10 даёт последнюю цифру, // 10 убирает её."}]}]},{"id":"u4","title":"Раздел 4. Списки","lessons":[{"id":"l16","title":"Что такое список","emoji":"📋","intro":"Список хранит много значений сразу: <code>a = [10, 20, 30]</code>. Номера (индексы) начинаются с <b>0</b>: <code>a[0]</code> — первый элемент, <code>a[-1]</code> — последний.","questions":[{"type":"output","q":"Что выведет код?","code":"fruits = [\"яблоко\", \"банан\", \"киви\"]\nprint(fruits[0])","options":["яблоко","банан","киви","Ошибку"],"explain":"Индекс 0 — первый элемент."},{"type":"output","q":"Что выведет код?","code":"nums = [10, 20, 30]\nprint(nums[2])","options":["30","20","10","Ошибку"],"explain":"0 → 10, 1 → 20, 2 → 30."},{"type":"output","q":"Отрицательный индекс считает с конца. Что выведет код?","code":"nums = [10, 20, 30]\nprint(nums[-1])","options":["30","10","-1","Ошибку"],"explain":"-1 — последний элемент, -2 — предпоследний."},{"type":"output","q":"Что выведет код?","code":"a = [1, 2, 3]\nprint(len(a))","options":["3","2","6","[1, 2, 3]"],"explain":"len() показывает количество элементов."},{"type":"bug","q":"Почему код упадёт?","code":"a = [1, 2, 3]\nprint(a[3])","options":["Элемента с индексом 3 нет — нумерация с 0","Нельзя печатать списки","Нужны круглые скобки","Он не упадёт"],"explain":"Индексы этого списка — 0, 1, 2. Индекс 3 — IndexError."},{"type":"input","q":"Что выведет код? Напиши ответ.","code":"pets = [\"кот\", \"пёс\", \"хомяк\"]\nprint(pets[1])","answers":["пёс"],"explain":"Индекс 1 — второй элемент."}]},{"id":"l17","title":"Меняем список","emoji":"✏️","intro":"<code>append(x)</code> — добавить в конец, <code>pop()</code> — забрать последний, <code>remove(x)</code> — удалить по значению, <code>sort()</code> — отсортировать.","questions":[{"type":"output","q":"Что выведет код?","code":"a = [1, 2]\na.append(3)\nprint(a)","options":["[1, 2, 3]","[3, 1, 2]","[1, 2]","3"],"explain":"append добавляет в конец."},{"type":"output","q":"Элемент можно заменить. Что выведет код?","code":"a = [5, 6, 7]\na[0] = 9\nprint(a)","options":["[9, 6, 7]","[5, 6, 7, 9]","[9, 5, 6, 7]","Ошибку"],"explain":"a[0] = 9 заменил первый элемент."},{"type":"output","q":"Что выведет код?","code":"a = [1, 2, 3]\nx = a.pop()\nprint(x, a)","options":["3 [1, 2]","1 [2, 3]","3 [1, 2, 3]","[1, 2]"],"explain":"pop() забирает последний элемент и возвращает его."},{"type":"output","q":"Что выведет код?","code":"a = [3, 1, 2]\na.sort()\nprint(a)","options":["[1, 2, 3]","[3, 2, 1]","[3, 1, 2]","None"],"explain":"sort() упорядочивает список по возрастанию."},{"type":"output","q":"Что выведет код?","code":"a = [\"a\", \"b\", \"c\"]\na.remove(\"b\")\nprint(a)","options":["['a', 'c']","['a', 'b']","['b']","Ошибку"],"explain":"remove удаляет элемент по значению. Строки в списке Python печатает в одинарных кавычках."},{"type":"input","q":"Какой метод добавляет элемент в конец списка?","answers":["append","append()"],"explain":"append — «добавить»."}]},{"id":"l18","title":"Перебор списка","emoji":"🔍","intro":"<code>for x in список:</code> проходит по всем элементам. Полезное: <code>sum()</code> — сумма, <code>max()</code>, <code>min()</code>, а <code>in</code> проверяет, есть ли элемент.","questions":[{"type":"output","q":"Что выведет код?","code":"for x in [2, 4, 6]:\n    print(x * 10)","out":"20\n40\n60","options":["20, 40, 60 — каждое с новой строки","[20, 40, 60]","2 4 6","120"],"explain":"Каждый элемент умножили на 10 и напечатали."},{"type":"output","q":"Что выведет код?","code":"print(sum([1, 2, 3, 4]))","options":["10","4","24","[1, 2, 3, 4]"],"explain":"sum складывает все элементы."},{"type":"output","q":"Что выведет код?","code":"print(max([3, 9, 2]), min([3, 9, 2]))","options":["9 2","2 9","9","3 2"],"explain":"max — наибольший, min — наименьший."},{"type":"output","q":"Что выведет код?","code":"print(5 in [1, 2, 3])","options":["False","True","5","Ошибку"],"explain":"Числа 5 в списке нет."},{"type":"output","q":"Код собирает чётные числа. Что выведет?","code":"nums = [1, 2, 3, 4, 5, 6]\nevens = []\nfor n in nums:\n    if n % 2 == 0:\n        evens.append(n)\nprint(evens)","options":["[2, 4, 6]","[1, 3, 5]","3","[1, 2, 3, 4, 5, 6]"],"explain":"Пустой список + append внутри цикла — классический приём."},{"type":"input","q":"Среднее арифметическое. Что выведет код?","code":"scores = [5, 3, 4]\nprint(sum(scores) / len(scores))","answers":["4.0"],"explain":"12 / 3 = 4.0. Деление / всегда даёт дробное число."}]},{"id":"l19","title":"Срезы","emoji":"✂️","intro":"Срез берёт кусок: <code>a[1:3]</code> — с индекса 1 до 3 (не включая). <code>a[:2]</code> — с начала, <code>a[3:]</code> — до конца, <code>a[::-1]</code> — задом наперёд.","questions":[{"type":"output","q":"Что выведет код?","code":"a = [0, 1, 2, 3, 4]\nprint(a[1:3])","options":["[1, 2]","[1, 2, 3]","[0, 1, 2]","[2, 3]"],"explain":"Индексы 1 и 2. Конец среза (3) не входит."},{"type":"output","q":"Что выведет код?","code":"a = [0, 1, 2, 3, 4]\nprint(a[:2])","options":["[0, 1]","[0, 1, 2]","[2, 3, 4]","[1, 2]"],"explain":"С начала до индекса 2, не включая."},{"type":"output","q":"Что выведет код?","code":"a = [0, 1, 2, 3, 4]\nprint(a[3:])","options":["[3, 4]","[4]","[0, 1, 2]","[3]"],"explain":"С индекса 3 до самого конца."},{"type":"output","q":"Что выведет код?","code":"a = [1, 2, 3]\nprint(a[::-1])","options":["[3, 2, 1]","[1, 2, 3]","[3]","Ошибку"],"explain":"Шаг -1 — идём с конца. Так разворачивают список."},{"type":"output","q":"Срезы работают и со строками. Что выведет код?","code":"print(\"Python\"[0:2])","options":["Py","Pyt","P","on"],"explain":"Буквы с индексами 0 и 1."},{"type":"input","q":"Что выведет код? Напиши ответ.","code":"print(\"питон\"[::-1])","answers":["нотип"],"explain":"Строка задом наперёд."}]},{"id":"l20","title":"Списки из строк и range","emoji":"🧱","intro":"<code>list(range(4))</code> делает список чисел. <code>\"a,b\".split(\",\")</code> режет строку в список, а <code>\"-\".join(список)</code> склеивает обратно.","questions":[{"type":"output","q":"Что выведет код?","code":"print(list(range(4)))","options":["[0, 1, 2, 3]","[1, 2, 3, 4]","range(4)","[0, 1, 2, 3, 4]"],"explain":"list() превращает range в настоящий список."},{"type":"output","q":"Что выведет код?","code":"print(\"a,b,c\".split(\",\"))","options":["['a', 'b', 'c']","abc","['a,b,c']","a b c"],"explain":"split режет строку по запятым."},{"type":"output","q":"Что выведет код?","code":"print(\"-\".join([\"1\", \"2\", \"3\"]))","options":["1-2-3","['1', '2', '3']","123","-1-2-3-"],"explain":"join склеивает элементы, ставя между ними «-»."},{"type":"output","q":"split() без аргумента режет по пробелам. Что выведет код?","code":"words = \"я учу питон\".split()\nprint(len(words))","options":["3","11","1","2"],"explain":"Получился список из трёх слов."},{"type":"output","q":"Списки можно складывать. Что выведет код?","code":"a = [1, 2] + [3]\nprint(a)","options":["[1, 2, 3]","[4, 2]","[[1, 2], [3]]","Ошибку"],"explain":"+ соединяет списки в один."},{"type":"input","q":"Что выведет код? Напиши ответ.","code":"print([0] * 3)","answers":["[0, 0, 0]"],"explain":"Список можно «размножить», как строку."}]},{"id":"p4a","title":"Практика: списки","emoji":"💻","intro":"Первая строка в каждой задаче уже читает числа из ввода в список <code>nums</code>. Например, ввод <code>1 2 3</code> превратится в <code>[1, 2, 3]</code>.","questions":[{"type":"code","q":"Сумма списка","task":"Выведи сумму всех чисел в списке <code>nums</code>.","starter":"nums = [int(x) for x in input().split()]  # эта строка уже читает числа в список nums\n","tests":[{"stdin":"1 2 3","out":"6"},{"stdin":"10","out":"10"},{"stdin":"5 -5","out":"0"}],"hint":"Есть готовая функция <code>sum()</code>.","solution":"nums = [int(x) for x in input().split()]  # эта строка уже читает числа в список nums\nprint(sum(nums))","explain":"sum() складывает все элементы."},{"type":"code","q":"Максимум вручную","task":"Выведи самое большое число из <code>nums</code>, <b>не используя max()</b>.","starter":"nums = [int(x) for x in input().split()]  # эта строка уже читает числа в список nums\n","tests":[{"stdin":"3 9 2","out":"9"},{"stdin":"-5 -2 -9","out":"-2"},{"stdin":"4","out":"4"}],"hint":"Начни с <code>best = nums[0]</code> и пройди циклом по остальным.","solution":"nums = [int(x) for x in input().split()]  # эта строка уже читает числа в список nums\nbest = nums[0]\nfor x in nums:\n    if x > best:\n        best = x\nprint(best)","explain":"Начинать с nums[0], а не с 0 — иначе для отрицательных чисел ответ будет неверным."},{"type":"code","q":"Только чётные","task":"Выведи список только чётных чисел из <code>nums</code> (в том же порядке).","starter":"nums = [int(x) for x in input().split()]  # эта строка уже читает числа в список nums\n","tests":[{"stdin":"1 2 3 4","out":"[2, 4]"},{"stdin":"1 3","out":"[]"},{"stdin":"6 6 7","out":"[6, 6]"}],"hint":"Пустой список <code>evens = []</code> и <code>append</code> в цикле.","solution":"nums = [int(x) for x in input().split()]  # эта строка уже читает числа в список nums\nevens = []\nfor x in nums:\n    if x % 2 == 0:\n        evens.append(x)\nprint(evens)","explain":"Фильтрация списка — частая задача."},{"type":"code","q":"Среднее","task":"Выведи среднее арифметическое чисел из <code>nums</code>.","starter":"nums = [int(x) for x in input().split()]  # эта строка уже читает числа в список nums\n","tests":[{"stdin":"2 4","out":"3.0"},{"stdin":"1 2 3 4","out":"2.5"},{"stdin":"7","out":"7.0"}],"hint":"Сумма, делённая на количество: <code>sum(nums) / len(nums)</code>.","solution":"nums = [int(x) for x in input().split()]  # эта строка уже читает числа в список nums\nprint(sum(nums) / len(nums))","explain":"Деление / всегда даёт дробное число."}]},{"id":"p4b","title":"Практика: работа со списками","emoji":"🧱","intro":"Разворот, повторы, второе место — задачи, которые часто дают на собеседованиях.","questions":[{"type":"code","q":"Задом наперёд","task":"Выведи список <code>nums</code> в обратном порядке.","starter":"nums = [int(x) for x in input().split()]  # эта строка уже читает числа в список nums\n","tests":[{"stdin":"1 2 3","out":"[3, 2, 1]"},{"stdin":"5","out":"[5]"}],"hint":"Срез с шагом -1.","solution":"nums = [int(x) for x in input().split()]  # эта строка уже читает числа в список nums\nprint(nums[::-1])","explain":"nums[::-1] — новый список задом наперёд."},{"type":"code","q":"Больше среднего","task":"Выведи, сколько чисел в <code>nums</code> строго больше среднего арифметического.","starter":"nums = [int(x) for x in input().split()]  # эта строка уже читает числа в список nums\n","tests":[{"stdin":"1 2 3 4 10","out":"1"},{"stdin":"5 5 5","out":"0"},{"stdin":"1 9","out":"1"}],"hint":"Сначала посчитай среднее, потом пройди циклом и считай.","solution":"nums = [int(x) for x in input().split()]  # эта строка уже читает числа в список nums\navg = sum(nums) / len(nums)\ncount = 0\nfor x in nums:\n    if x > avg:\n        count += 1\nprint(count)","explain":"Задачу удобно решать в два прохода: сначала среднее, потом подсчёт."},{"type":"code","q":"Без повторов","task":"Выведи список чисел из <code>nums</code> без повторов, сохранив порядок первого появления.","starter":"nums = [int(x) for x in input().split()]  # эта строка уже читает числа в список nums\n","tests":[{"stdin":"1 2 2 3 1","out":"[1, 2, 3]"},{"stdin":"5 5 5","out":"[5]"},{"stdin":"3 1 2","out":"[3, 1, 2]"}],"hint":"Новый список, и добавляй x, только если <code>x not in result</code>.","solution":"nums = [int(x) for x in input().split()]  # эта строка уже читает числа в список nums\nresult = []\nfor x in nums:\n    if x not in result:\n        result.append(x)\nprint(result)","explain":"set убрал бы повторы, но перепутал бы порядок — поэтому вручную."},{"type":"code","q":"Второе место","task":"Выведи второе по величине <b>различное</b> число из <code>nums</code> (в списке есть хотя бы два разных числа).","starter":"nums = [int(x) for x in input().split()]  # эта строка уже читает числа в список nums\n","tests":[{"stdin":"3 1 4 4 2","out":"3"},{"stdin":"10 20","out":"10"},{"stdin":"5 5 1","out":"1"}],"hint":"Убери повторы через <code>set</code>, отсортируй и возьми предпоследний: <code>sorted(set(nums))[-2]</code>.","solution":"nums = [int(x) for x in input().split()]  # эта строка уже читает числа в список nums\nprint(sorted(set(nums))[-2])","explain":"set — без повторов, sorted — по возрастанию, [-2] — предпоследний."}]}]},{"id":"u5","title":"Раздел 5. Строки","lessons":[{"id":"l21","title":"Буквы и методы","emoji":"🔠","intro":"Строка — как список букв: <code>s[0]</code> — первая, <code>s[-1]</code> — последняя. Методы: <code>lower()</code>, <code>upper()</code>, <code>strip()</code> (убрать пробелы по краям), <code>replace(a, b)</code>.","questions":[{"type":"output","q":"Что выведет код?","code":"s = \"Питоша\"\nprint(s[0])","options":["П","и","а","Питоша"],"explain":"Индекс 0 — первая буква."},{"type":"output","q":"Что выведет код?","code":"s = \"Питоша\"\nprint(s[-1])","options":["а","П","ш","Ошибку"],"explain":"-1 — последняя буква."},{"type":"output","q":"Что выведет код?","code":"print(\"ПРИВЕТ\".lower())","options":["привет","ПРИВЕТ","Привет","lower"],"explain":"lower() делает все буквы маленькими."},{"type":"output","q":"Что выведет код?","code":"print(\"  ку  \".strip())","options":["ку","  ку","ку  ","  ку  "],"explain":"strip() убирает пробелы в начале и в конце."},{"type":"output","q":"Что выведет код?","code":"print(\"мама мыла раму\".replace(\"мама\", \"папа\"))","options":["папа мыла раму","мама мыла раму","папа мыла папу","Ошибку"],"explain":"replace заменяет одну часть строки на другую."},{"type":"input","q":"Что выведет код? Напиши ответ.","code":"print(\"abc\" * 2)","answers":["abcabc"],"explain":"Строку можно повторить умножением."}]},{"id":"l22","title":"Поиск в строке","emoji":"🔎","intro":"<code>count(x)</code> — сколько раз встречается, <code>find(x)</code> — где (индекс), <code>in</code> — есть ли вообще. <code>startswith</code> — начинается ли с…","questions":[{"type":"output","q":"Что выведет код?","code":"print(\"банан\".count(\"а\"))","options":["2","1","3","5"],"explain":"Буква «а» встречается 2 раза."},{"type":"output","q":"Что выведет код?","code":"print(\"питон\".find(\"т\"))","options":["2","3","1","True"],"explain":"п(0) и(1) т(2). find возвращает индекс."},{"type":"output","q":"Что выведет код?","code":"print(\"кот\" in \"скоторезка\")","options":["True","False","кот","Ошибку"],"explain":"«с-кот-орезка»: «кот» есть внутри."},{"type":"output","q":"Что выведет код?","code":"print(\"Hello\".startswith(\"He\"))","options":["True","False","He","Ошибку"],"explain":"Строка начинается с «He»."},{"type":"output","q":"isdigit() проверяет, только ли цифры. Что выведет код?","code":"print(\"123\".isdigit(), \"12a\".isdigit())","options":["True False","True True","False False","False True"],"explain":"В «12a» есть буква — значит не только цифры."},{"type":"input","q":"Что выведет код? Напиши ответ.","code":"print(len(\"Выселки\"))","answers":["7"],"explain":"В слове «Выселки» 7 букв."}]},{"id":"l23","title":"Форматирование","emoji":"🧾","intro":"f-строки умеют больше: <code>{x:.2f}</code> — показать 2 знака после точки. <code>str(5)</code> превращает число в строку, <code>int(\"7\")</code> — строку в число.","questions":[{"type":"output","q":"Что выведет код?","code":"name = \"Душка\"\nage = 12\nprint(f\"{name}, {age} лет\")","options":["Душка, 12 лет","{name}, {age} лет","name, age лет","Ошибку"],"explain":"Значения подставились в {скобки}."},{"type":"output","q":"Что выведет код?","code":"pi = 3.14159\nprint(f\"{pi:.2f}\")","options":["3.14","3.14159","3.1","3"],"explain":".2f — два знака после точки."},{"type":"output","q":"Что выведет код?","code":"x = 7\nprint(f\"{x} * 2 = {x * 2}\")","options":["7 * 2 = 14","7 * 2 = 7 * 2","x * 2 = 14","14"],"explain":"Внутри {} можно считать."},{"type":"output","q":"Что выведет код?","code":"print(str(5) + \"5\")","options":["55","10","5 5","Ошибку"],"explain":"Обе части — строки, поэтому они склеились."},{"type":"output","q":"Что выведет код?","code":"print(int(\"7\") + 3)","options":["10","73","7 3","Ошибку"],"explain":"int(\"7\") — это число 7, а 7 + 3 = 10."},{"type":"input","q":"Что выведет код? Напиши ответ.","code":"n = 3\nprint(f\"У меня {n} кота\")","answers":["У меня 3 кота"],"explain":"n подставилось в текст."}]},{"id":"l24","title":"Практика: строки","emoji":"🧪","intro":"Строки <b>нельзя менять по одной букве</b> — можно только собрать новую. Палиндром — слово, которое читается одинаково с обеих сторон.","questions":[{"type":"output","q":"Код собирает строку задом наперёд. Что выведет?","code":"s = \"Привет\"\nresult = \"\"\nfor ch in s:\n    result = ch + result\nprint(result)","options":["тевирП","Привет","П","Ошибку"],"explain":"Каждую новую букву ставим в начало — строка разворачивается."},{"type":"output","q":"Проверка на палиндром. Что выведет?","code":"word = \"шалаш\"\nprint(word == word[::-1])","options":["True","False","шалаш","Ошибку"],"explain":"«шалаш» задом наперёд — тоже «шалаш»."},{"type":"output","q":"Что выведет код?","code":"text = \"один два три\"\nprint(text.split()[1])","options":["два","один","три","д"],"explain":"split дал список слов, [1] — второе слово."},{"type":"output","q":"Что выведет код?","code":"print(\"python\".capitalize())","options":["Python","PYTHON","python","pYTHON"],"explain":"capitalize — первая буква большая, остальные маленькие."},{"type":"bug","q":"Почему код упадёт?","code":"name = \"Ярослав\"\nname[0] = \"я\"","options":["Строки нельзя менять по одной букве","Нельзя писать маленькую я","Нужен print","Он не упадёт"],"explain":"Строки неизменяемы. Правильно: name = \"я\" + name[1:]."},{"type":"input","q":"Что выведет код? Напиши ответ.","code":"print(\"-\" * 5)","answers":["-----"],"explain":"Пять чёрточек."}]},{"id":"p5a","title":"Практика: строки","emoji":"💻","intro":"Работаем с текстом: разворачиваем, ищем, считаем.","questions":[{"type":"code","q":"Перевёртыш","task":"Прочитай строку и выведи её задом наперёд.","starter":"s = input()\n","tests":[{"stdin":"кот","out":"ток"},{"stdin":"Python","out":"nohtyP"},{"stdin":"а","out":"а"}],"hint":"Срез <code>s[::-1]</code>.","solution":"s = input()\nprint(s[::-1])","explain":"Срезы работают со строками так же, как со списками."},{"type":"code","q":"Палиндром","task":"Прочитай слово и выведи <code>Да</code>, если оно читается одинаково с обеих сторон (без учёта больших букв), иначе <code>Нет</code>.","starter":"","tests":[{"stdin":"Шалаш","out":"Да"},{"stdin":"кот","out":"Нет"},{"stdin":"А","out":"Да"},{"stdin":"Казак","out":"Да"}],"hint":"Сначала <code>s = input().lower()</code>, потом сравни с <code>s[::-1]</code>.","solution":"s = input().lower()\nif s == s[::-1]:\n    print(\"Да\")\nelse:\n    print(\"Нет\")","explain":"lower() нужен, чтобы «Ш» и «ш» считались одинаковыми."},{"type":"code","q":"Гласные","task":"Прочитай слово на русском и выведи, сколько в нём гласных (а, е, ё, и, о, у, ы, э, ю, я).","starter":"","tests":[{"stdin":"привет","out":"2"},{"stdin":"ыыы","out":"3"},{"stdin":"бвг","out":"0"},{"stdin":"Питоша","out":"3"}],"hint":"Пройди по буквам: <code>if ch in \"аеёиоуыэюя\"</code>. Не забудь про большие буквы — <code>lower()</code>.","solution":"s = input().lower()\ncount = 0\nfor ch in s:\n    if ch in \"аеёиоуыэюя\":\n        count += 1\nprint(count)","explain":"Оператор in со строкой проверяет, есть ли там буква."},{"type":"code","q":"С большой буквы","task":"Прочитай фразу и выведи её, сделав первую букву каждого слова большой.<br><code>я учу питон</code> → <code>Я Учу Питон</code>","starter":"","tests":[{"stdin":"я учу питон","out":"Я Учу Питон"},{"stdin":"привет","out":"Привет"}],"hint":"split() → capitalize() для каждого слова → \" \".join(...)","solution":"words = input().split()\nresult = []\nfor w in words:\n    result.append(w.capitalize())\nprint(\" \".join(result))","explain":"split → обработать каждое слово → join: частая цепочка."}]},{"id":"p5b","title":"Практика: текст посложнее","emoji":"🔐","intro":"Самое длинное слово, подсчёт слов и настоящий шифр Цезаря!","questions":[{"type":"code","q":"Самое длинное слово","task":"Прочитай строку и выведи самое длинное слово. Если таких несколько — первое из них.","starter":"","tests":[{"stdin":"кот слон ёж","out":"слон"},{"stdin":"аа бб","out":"аа"},{"stdin":"питон","out":"питон"}],"hint":"Пройди по словам и запоминай слово, если оно длиннее лучшего.","solution":"words = input().split()\nbest = words[0]\nfor w in words:\n    if len(w) > len(best):\n        best = w\nprint(best)","explain":"Строго «больше», а не «больше или равно» — тогда при равенстве остаётся первое слово."},{"type":"code","q":"Пробелы → подчёркивания","task":"Прочитай строку и замени все пробелы на <code>_</code>.","starter":"","tests":[{"stdin":"привет мир","out":"привет_мир"},{"stdin":"a b c","out":"a_b_c"},{"stdin":"слово","out":"слово"}],"hint":"Метод <code>replace(\" \", \"_\")</code>.","solution":"print(input().replace(\" \", \"_\"))","explain":"Так делают имена файлов и переменных из фраз."},{"type":"code","q":"Сколько слов","task":"Прочитай строку и выведи, сколько в ней слов.","starter":"","tests":[{"stdin":"один два три","out":"3"},{"stdin":"слово","out":"1"},{"stdin":"я  люблю   питон","out":"3"}],"hint":"<code>len(input().split())</code> — split без аргумента сам справится с лишними пробелами.","solution":"print(len(input().split()))","explain":"split() без аргументов игнорирует лишние пробелы."},{"type":"code","q":"Шифр Цезаря","task":"Прочитай строку из маленьких латинских букв и знаков. Сдвинь каждую букву на 1 вперёд по алфавиту (<code>z</code> → <code>a</code>), остальные символы не трогай.<br><code>abc</code> → <code>bcd</code>","starter":"","tests":[{"stdin":"abc","out":"bcd"},{"stdin":"xyz","out":"yza"},{"stdin":"hi!","out":"ij!"}],"hint":"Алфавит: <code>abc = \"abcdefghijklmnopqrstuvwxyz\"</code>. Номер буквы — <code>abc.find(ch)</code>, следующая — <code>abc[(i + 1) % 26]</code>.","solution":"abc = \"abcdefghijklmnopqrstuvwxyz\"\ns = input()\nresult = \"\"\nfor ch in s:\n    i = abc.find(ch)\n    if i == -1:\n        result += ch\n    else:\n        result += abc[(i + 1) % 26]\nprint(result)","explain":"% 26 «заворачивает» z обратно в a. Так шифровал ещё Юлий Цезарь!"}]}]},{"id":"u6","title":"Раздел 6. Функции","lessons":[{"id":"l25","title":"Свои функции","emoji":"🛠️","intro":"Функция — свой «приём», который можно вызывать много раз. Создаём: <code>def имя():</code> и код с отступом. Вызываем: <code>имя()</code>.","questions":[{"type":"output","q":"Что выведет код?","code":"def hello():\n    print(\"Привет!\")\nhello()\nhello()","out":"Привет!\nПривет!","options":["Привет! два раза","Привет! один раз","Ничего","Ошибку"],"explain":"Функцию вызвали два раза — два приветствия."},{"type":"output","q":"А если функцию не вызвать?","code":"def hello():\n    print(\"Привет!\")","out":"","options":["Ничего — функцию не вызвали","Привет!","hello","Ошибку"],"explain":"def только создаёт функцию. Код внутри выполнится, когда её вызовут."},{"type":"input","q":"Какое слово создаёт функцию?","answers":["def"],"explain":"def — от слова define, «определить»."},{"type":"bug","q":"Где ошибка?","code":"def say()\n    print(\"Ура\")","options":["Нет двоеточия после say()","Нельзя называть функцию say","Нужно писать Def","Ошибки нет"],"explain":"Как и у if, после def нужно двоеточие."},{"type":"output","q":"В скобках можно передать значение (параметр). Что выведет код?","code":"def greet(name):\n    print(\"Привет,\", name)\ngreet(\"Ира\")","options":["Привет, Ира","Привет, name","Привет,Ира","Ошибку"],"explain":"name получил значение «Ира». print ставит пробел между значениями."},{"type":"output","q":"Что выведет код?","code":"def square(x):\n    print(x * x)\nsquare(4)\nsquare(5)","out":"16\n25","options":["16, потом 25","4, потом 5","41","Ошибку"],"explain":"Одна функция — разные значения."}]},{"id":"l26","title":"return — вернуть ответ","emoji":"↩️","intro":"<code>return</code> отдаёт результат обратно в программу, и его можно сохранить или использовать дальше. После return функция сразу заканчивается.","questions":[{"type":"output","q":"Что выведет код?","code":"def double(x):\n    return x * 2\nprint(double(5))","options":["10","5","double","None"],"explain":"double(5) вернула 10, а print её показал."},{"type":"output","q":"Что выведет код?","code":"def add(a, b):\n    return a + b\nresult = add(2, 3)\nprint(result * 10)","options":["50","5","23","510"],"explain":"add вернула 5, а 5 × 10 = 50."},{"type":"choice","q":"Чем return отличается от print?","options":["return отдаёт значение программе, print только показывает на экране","Ничем","print быстрее","return печатает красивее"],"explain":"Результат print нельзя использовать дальше, а результат return — можно."},{"type":"output","q":"Что выведет код?","code":"def f():\n    return 1\n    print(\"Не выполнится\")\nprint(f())","options":["1","Не выполнится","1 и Не выполнится","None"],"explain":"После return функция заканчивается — print внутри не сработал."},{"type":"output","q":"Что выведет код?","code":"def is_even(n):\n    return n % 2 == 0\nprint(is_even(10))","options":["True","False","0","10"],"explain":"Функция может вернуть True/False — это удобно для проверок."},{"type":"input","q":"Что выведет код? Напиши ответ.","code":"def f(x):\n    return x + 1\nprint(f(f(1)))","answers":["3"],"explain":"Сначала f(1) = 2, потом f(2) = 3."}]},{"id":"l27","title":"Параметры","emoji":"🎛️","intro":"У параметра может быть значение по умолчанию: <code>def hi(name=\"друг\")</code>. Аргументы можно передавать по имени: <code>info(age=12, name=\"Яр\")</code>.","questions":[{"type":"output","q":"Что выведет код?","code":"def hi(name=\"друг\"):\n    print(\"Привет,\", name)\nhi()","options":["Привет, друг","Привет,","Привет, name","Ошибку"],"explain":"Ничего не передали — взялось значение по умолчанию."},{"type":"output","q":"Что выведет код?","code":"def hi(name=\"друг\"):\n    print(\"Привет,\", name)\nhi(\"Коля\")","options":["Привет, Коля","Привет, друг","Привет, друг Коля","Ошибку"],"explain":"Передали «Коля» — он заменил значение по умолчанию."},{"type":"output","q":"Что выведет код?","code":"def power(x, n=2):\n    return x ** n\nprint(power(3), power(2, 3))","options":["9 8","9 6","6 8","3 2"],"explain":"3² = 9, а 2³ = 8."},{"type":"output","q":"Что выведет код?","code":"def info(name, age):\n    print(name, age)\ninfo(age=12, name=\"Яр\")","options":["Яр 12","12 Яр","name age","Ошибку"],"explain":"Аргументы по имени можно передавать в любом порядке."},{"type":"bug","q":"Почему код упадёт?","code":"def add(a, b):\n    return a + b\nprint(add(1))","options":["Не передали второй аргумент b","Нельзя складывать числа","Нет print внутри","Он не упадёт"],"explain":"Функция ждёт два значения, а получила одно — TypeError."},{"type":"input","q":"Что выведет код? Напиши ответ.","code":"def tag(text, sym=\"*\"):\n    return sym + text + sym\nprint(tag(\"ок\"))","answers":["*ок*"],"explain":"sym по умолчанию — звёздочка."}]},{"id":"l28","title":"Где живут переменные","emoji":"🏠","intro":"Переменная, созданная внутри функции, — <b>локальная</b>: снаружи её не видно. <code>global x</code> разрешает менять переменную снаружи (но так делают редко).","questions":[{"type":"output","q":"Что выведет код?","code":"x = 5\ndef f():\n    x = 10\n    print(x)\nf()\nprint(x)","out":"10\n5","options":["10, потом 5","10, потом 10","5, потом 5","Ошибку"],"explain":"x внутри функции — отдельная переменная, внешний x не изменился."},{"type":"bug","q":"Почему код упадёт?","code":"def f():\n    y = 3\nf()\nprint(y)","options":["y существует только внутри функции","Нет return","Нельзя называть переменную y","Он не упадёт"],"explain":"Снаружи y не видно — NameError."},{"type":"output","q":"Что выведет код?","code":"count = 0\ndef inc():\n    global count\n    count += 1\ninc()\ninc()\nprint(count)","options":["2","0","1","Ошибку"],"explain":"global разрешил менять внешнюю переменную."},{"type":"choice","q":"Что такое локальная переменная?","options":["Созданная внутри функции, снаружи её не видно","Самая важная переменная","Переменная со словом local","Переменная, которую видно везде"],"explain":"Локальная — «живёт» только внутри своей функции."},{"type":"output","q":"Что выведет код?","code":"def f(a):\n    a = a + 1\n    return a\nx = 1\nf(x)\nprint(x)","options":["1","2","None","Ошибку"],"explain":"Результат f(x) никуда не сохранили, а x остался 1."},{"type":"input","q":"Что выведет код? Напиши ответ.","code":"def f():\n    return \"внутри\"\nprint(f())","answers":["внутри"],"explain":"Функция вернула строку."}]},{"id":"l29","title":"Практика: функции","emoji":"🧠","intro":"Хорошая функция делает одно дело. Функция может даже вызывать сама себя — это <b>рекурсия</b>.","questions":[{"type":"output","q":"Что выведет код?","code":"def max2(a, b):\n    if a > b:\n        return a\n    return b\nprint(max2(4, 9))","options":["9","4","a","None"],"explain":"4 > 9 — ложь, поэтому вернули b."},{"type":"output","q":"Функция считает гласные. Что выведет?","code":"def count_vowels(s):\n    n = 0\n    for ch in s:\n        if ch in \"аеёиоуыэюя\":\n            n += 1\n    return n\nprint(count_vowels(\"питоша\"))","options":["3","2","6","4"],"explain":"и, о, а — три гласные."},{"type":"output","q":"Рекурсия: факториал. Что выведет?","code":"def fact(n):\n    if n == 1:\n        return 1\n    return n * fact(n - 1)\nprint(fact(4))","options":["24","10","4","Бесконечно"],"explain":"4 × 3 × 2 × 1 = 24. Когда n стало 1, рекурсия остановилась."},{"type":"choice","q":"Что такое рекурсия?","options":["Когда функция вызывает сама себя","Цикл while","Ошибка в функции","Функция без return"],"explain":"Главное — условие остановки, иначе вызовы будут бесконечными."},{"type":"output","q":"sorted() возвращает новый список. Что выведет код?","code":"nums = [3, 1, 2]\nprint(sorted(nums), nums)","options":["[1, 2, 3] [3, 1, 2]","[1, 2, 3] [1, 2, 3]","[3, 1, 2] [1, 2, 3]","None [3, 1, 2]"],"explain":"sorted не меняет исходный список, а sort() — меняет."},{"type":"input","q":"Что выведет код? Напиши ответ.","code":"def avg(a):\n    return sum(a) / len(a)\nprint(avg([2, 4]))","answers":["3.0"],"explain":"(2 + 4) / 2 = 3.0."}]},{"id":"p6a","title":"Практика: функции","emoji":"💻","intro":"Теперь пишешь <b>функции</b>. Питоша сам вызовет её с разными значениями и сверит ответ. Печатать ничего не нужно — используй <code>return</code>.","questions":[{"type":"code","q":"Квадрат","task":"Напиши функцию <code>square(x)</code>, которая возвращает квадрат числа.","starter":"def square(x):\n    # верни квадрат x\n    pass\n","tests":[{"expr":"square(5)","expect":"25"},{"expr":"square(-3)","expect":"9"},{"expr":"square(0)","expect":"0"}],"hint":"<code>return x * x</code>","solution":"def square(x):\n    return x * x","explain":"return отдаёт результат тому, кто вызвал функцию."},{"type":"code","q":"Чётное ли","task":"Напиши функцию <code>is_even(n)</code>, которая возвращает <code>True</code>, если n чётное, иначе <code>False</code>.","starter":"def is_even(n):\n    pass\n","tests":[{"expr":"is_even(4)","expect":"True"},{"expr":"is_even(7)","expect":"False"},{"expr":"is_even(0)","expect":"True"}],"hint":"Сравнение уже даёт True/False: <code>return n % 2 == 0</code>","solution":"def is_even(n):\n    return n % 2 == 0","explain":"Не нужно писать if — само сравнение и есть ответ."},{"type":"code","q":"Максимум из трёх","task":"Напиши функцию <code>max3(a, b, c)</code>, которая возвращает наибольшее из трёх чисел.","starter":"def max3(a, b, c):\n    pass\n","tests":[{"expr":"max3(1, 5, 3)","expect":"5"},{"expr":"max3(-1, -5, -3)","expect":"-1"},{"expr":"max3(2, 2, 2)","expect":"2"},{"expr":"max3(1, 2, 9)","expect":"9"}],"hint":"Как в задаче «Наибольшее из трёх», только вместо print — return.","solution":"def max3(a, b, c):\n    best = a\n    if b > best:\n        best = b\n    if c > best:\n        best = c\n    return best","explain":"Функции превращают решения в инструменты, которые можно переиспользовать."},{"type":"code","q":"Приветствие","task":"Напиши функцию <code>greet(name=\"друг\")</code>, которая возвращает строку <code>Привет, NAME!</code>","starter":"def greet(name=\"друг\"):\n    pass\n","tests":[{"expr":"greet()","expect":"'Привет, друг!'"},{"expr":"greet(\"Ира\")","expect":"'Привет, Ира!'"}],"hint":"<code>return f\"Привет, {name}!\"</code>","solution":"def greet(name=\"друг\"):\n    return f\"Привет, {name}!\"","explain":"Если имя не передали, используется «друг»."}]},{"id":"p6b","title":"Практика: классика алгоритмов","emoji":"🧠","intro":"Числа Фибоначчи, простые числа — задачи, на которых учились все программисты.","questions":[{"type":"code","q":"Сколько раз буква","task":"Напиши функцию <code>count_char(s, ch)</code>, которая возвращает, сколько раз символ ch встречается в строке s. Без метода <code>count</code>!","starter":"def count_char(s, ch):\n    pass\n","tests":[{"expr":"count_char(\"банан\", \"а\")","expect":"2"},{"expr":"count_char(\"кот\", \"я\")","expect":"0"},{"expr":"count_char(\"ааа\", \"а\")","expect":"3"}],"hint":"Цикл по буквам и счётчик.","solution":"def count_char(s, ch):\n    n = 0\n    for c in s:\n        if c == ch:\n            n += 1\n    return n","explain":"Ты только что написал свою версию метода count!"},{"type":"code","q":"Фибоначчи","task":"Числа Фибоначчи: 1, 1, 2, 3, 5, 8… — каждое равно сумме двух предыдущих. Напиши <code>fib(n)</code>, возвращающую n-е число (fib(1) = 1, fib(2) = 1).","starter":"def fib(n):\n    pass\n","tests":[{"expr":"fib(1)","expect":"1"},{"expr":"fib(2)","expect":"1"},{"expr":"fib(10)","expect":"55"},{"expr":"fib(30)","expect":"832040"}],"hint":"Две переменные <code>a, b = 1, 1</code>, и n − 2 раза: <code>a, b = b, a + b</code>.","solution":"def fib(n):\n    a, b = 1, 1\n    for _ in range(n - 2):\n        a, b = b, a + b\n    return b","explain":"Решение циклом работает быстро даже для больших n."},{"type":"code","q":"Простое число","task":"Напиши <code>is_prime(n)</code>: True, если n простое (делится только на 1 и на себя, и n > 1).","starter":"def is_prime(n):\n    pass\n","tests":[{"expr":"is_prime(2)","expect":"True"},{"expr":"is_prime(1)","expect":"False"},{"expr":"is_prime(9)","expect":"False"},{"expr":"is_prime(13)","expect":"True"},{"expr":"is_prime(97)","expect":"True"}],"hint":"Если n < 2 — False. Иначе проверь делители от 2 до n − 1: нашёлся — False.","solution":"def is_prime(n):\n    if n < 2:\n        return False\n    for d in range(2, n):\n        if n % d == 0:\n            return False\n    return True","explain":"return внутри цикла сразу выходит из функции — удобно."},{"type":"code","q":"Сумма цифр","task":"Напиши <code>digits_sum(n)</code>, которая возвращает сумму цифр неотрицательного числа n.","starter":"def digits_sum(n):\n    pass\n","tests":[{"expr":"digits_sum(1234)","expect":"10"},{"expr":"digits_sum(0)","expect":"0"},{"expr":"digits_sum(9)","expect":"9"}],"hint":"Можно через строку: <code>for ch in str(n): s += int(ch)</code>.","solution":"def digits_sum(n):\n    s = 0\n    for ch in str(n):\n        s += int(ch)\n    return s","explain":"Перевести число в строку — удобный трюк для работы с цифрами."}]}]},{"id":"u7","title":"Раздел 7. Словари и коллекции","lessons":[{"id":"l30","title":"Словари","emoji":"📖","intro":"Словарь хранит пары «ключ: значение»: <code>{\"кот\": \"cat\"}</code>. Значение достают по ключу: <code>d[\"кот\"]</code>. <code>get(ключ, запасное)</code> не падает, если ключа нет.","questions":[{"type":"output","q":"Что выведет код?","code":"d = {\"кот\": \"cat\", \"пёс\": \"dog\"}\nprint(d[\"кот\"])","options":["cat","кот","dog","Ошибку"],"explain":"По ключу «кот» лежит «cat»."},{"type":"output","q":"Что выведет код?","code":"ages = {\"Ира\": 40}\nages[\"Коля\"] = 42\nprint(len(ages))","options":["2","1","42","Ошибку"],"explain":"Новая пара добавилась — теперь их две."},{"type":"bug","q":"Почему код упадёт?","code":"d = {\"a\": 1}\nprint(d[\"b\"])","options":["Ключа \"b\" в словаре нет","Нельзя печатать словарь","Ключи должны быть числами","Он не упадёт"],"explain":"Нет такого ключа — KeyError. Спасает d.get(\"b\")."},{"type":"output","q":"Что выведет код?","code":"d = {\"a\": 1}\nprint(d.get(\"b\", 0))","options":["0","1","None","Ошибку"],"explain":"Ключа нет — get вернул запасное значение 0."},{"type":"output","q":"Что выведет код?","code":"d = {\"x\": 1, \"y\": 2}\nfor k in d:\n    print(k)","out":"x\ny","options":["x и y — каждое с новой строки","1 и 2","x 1 y 2","{'x': 1, 'y': 2}"],"explain":"for по словарю перебирает ключи."},{"type":"input","q":"Что выведет код? Напиши ответ.","code":"d = {\"a\": 5}\nd[\"a\"] += 1\nprint(d[\"a\"])","answers":["6"],"explain":"Значение по ключу можно менять."}]},{"id":"l31","title":"Перебор словаря","emoji":"🗂️","intro":"<code>items()</code> даёт пары (ключ, значение), <code>keys()</code> — ключи, <code>values()</code> — значения. <code>in</code> проверяет, есть ли <b>ключ</b>.","questions":[{"type":"output","q":"Что выведет код?","code":"d = {\"a\": 1, \"b\": 2}\nfor k, v in d.items():\n    print(k, v)","out":"a 1\nb 2","options":["a 1 и b 2 на двух строках","a b","1 2","('a', 1) ('b', 2)"],"explain":"items() отдаёт сразу и ключ, и значение."},{"type":"output","q":"Что выведет код?","code":"d = {\"a\": 1, \"b\": 2}\nprint(list(d.keys()))","options":["['a', 'b']","[1, 2]","['a', 1, 'b', 2]","ab"],"explain":"keys() — все ключи."},{"type":"output","q":"Что выведет код?","code":"print(sum({\"a\": 3, \"b\": 4}.values()))","options":["7","34","ab","Ошибку"],"explain":"Сумма значений: 3 + 4."},{"type":"output","q":"Что выведет код?","code":"d = {\"a\": 1}\nprint(\"a\" in d, 1 in d)","options":["True False","True True","False True","False False"],"explain":"in проверяет ключи, а 1 — это значение, не ключ."},{"type":"output","q":"Подсчёт букв словарём. Что выведет код?","code":"count = {}\nfor ch in \"aab\":\n    count[ch] = count.get(ch, 0) + 1\nprint(count)","options":["{'a': 2, 'b': 1}","{'a': 1, 'b': 1}","{'aab': 3}","3"],"explain":"Классический приём: get(ch, 0) + 1."},{"type":"input","q":"Что выведет код? Напиши ответ.","code":"d = {\"x\": 10}\ndel d[\"x\"]\nprint(len(d))","answers":["0"],"explain":"del удалил единственную пару."}]},{"id":"l32","title":"Кортежи","emoji":"📦","intro":"Кортеж — как список, но в круглых скобках и <b>неизменяемый</b>: <code>t = (1, 2)</code>. Удобная штука: <code>a, b = 3, 4</code> — сразу две переменные.","questions":[{"type":"output","q":"Что выведет код?","code":"t = (1, 2, 3)\nprint(t[1])","options":["2","1","3","Ошибку"],"explain":"Индексы как у списка."},{"type":"bug","q":"Почему код упадёт?","code":"t = (1, 2)\nt[0] = 5","options":["Кортеж нельзя изменять","Нельзя хранить числа в кортеже","Нужны квадратные скобки для индекса","Он не упадёт"],"explain":"Кортеж после создания не меняется — TypeError."},{"type":"output","q":"Что выведет код?","code":"a, b = 3, 4\nprint(a + b)","options":["7","34","(3, 4)","Ошибку"],"explain":"a = 3, b = 4."},{"type":"output","q":"Обмен значениями. Что выведет код?","code":"a, b = 1, 2\na, b = b, a\nprint(a, b)","options":["2 1","1 2","2 2","Ошибку"],"explain":"В Python поменять местами можно в одну строку."},{"type":"choice","q":"Чем кортеж отличается от списка?","options":["Кортеж нельзя изменять после создания","В кортеже только числа","Кортеж всегда длиннее","Ничем"],"explain":"Поэтому кортежи используют для того, что не должно меняться."},{"type":"input","q":"Что выведет код? Напиши ответ.","code":"x, y, z = \"abc\"\nprint(y)","answers":["b"],"explain":"Строку тоже можно «распаковать» по буквам."}]},{"id":"l33","title":"Множества","emoji":"🔵","intro":"Множество <code>{1, 2, 3}</code> хранит только <b>уникальные</b> значения, без повторов и без порядка. <code>&amp;</code> — общие элементы, <code>|</code> — все вместе.","questions":[{"type":"output","q":"Что выведет код?","code":"s = {1, 2, 2, 3}\nprint(len(s))","options":["3","4","2","Ошибку"],"explain":"Повтор двойки выкинулся."},{"type":"output","q":"Какие разные буквы есть в слове? (sorted — по алфавиту)","code":"print(sorted(set(\"банан\")))","options":["['а', 'б', 'н']","['б', 'а', 'н', 'а', 'н']","['банан']","3"],"explain":"set убрал повторы, sorted расставил по алфавиту."},{"type":"output","q":"Что выведет код?","code":"a = {1, 2, 3}\nb = {2, 3, 4}\nprint(sorted(a & b))","options":["[2, 3]","[1, 2, 3, 4]","[1, 4]","[]"],"explain":"& — то, что есть в обоих."},{"type":"output","q":"Что выведет код?","code":"a = {1, 2}\nb = {2, 3}\nprint(sorted(a | b))","options":["[1, 2, 3]","[2]","[1, 2, 2, 3]","[1, 3]"],"explain":"| — всё вместе, без повторов."},{"type":"output","q":"Что выведет код?","code":"s = set()\ns.add(5)\ns.add(5)\nprint(s)","options":["{5}","{5, 5}","[5, 5]","Ошибку"],"explain":"Второй раз 5 не добавилась — она уже есть."},{"type":"input","q":"Сколько разных чисел? Что выведет код?","code":"print(len(set([1, 1, 1, 2])))","answers":["2"],"explain":"Разных всего два: 1 и 2."}]},{"id":"p7a","title":"Практика: словари","emoji":"💻","intro":"Словари — суперсила для подсчётов и поиска. Пишем функции, которые с ними работают.","questions":[{"type":"code","q":"Подсчёт слов","task":"Напиши <code>count_words(text)</code>: вернуть словарь «слово → сколько раз встретилось».","starter":"def count_words(text):\n    pass\n","tests":[{"expr":"count_words(\"кот пёс кот\")","expect":"{'кот': 2, 'пёс': 1}"},{"expr":"count_words(\"а\")","expect":"{'а': 1}"}],"hint":"<code>d[w] = d.get(w, 0) + 1</code> для каждого слова из <code>text.split()</code>.","solution":"def count_words(text):\n    d = {}\n    for w in text.split():\n        d[w] = d.get(w, 0) + 1\n    return d","explain":"Классический подсчёт через get."},{"type":"code","q":"Наоборот","task":"Напиши <code>invert(d)</code>: вернуть новый словарь, где ключи и значения поменялись местами.","starter":"def invert(d):\n    pass\n","tests":[{"expr":"invert({'a': 1, 'b': 2})","expect":"{1: 'a', 2: 'b'}"},{"expr":"invert({})","expect":"{}"}],"hint":"Новый словарь, и в цикле <code>for k, v in d.items(): new[v] = k</code>.","solution":"def invert(d):\n    new = {}\n    for k, v in d.items():\n        new[v] = k\n    return new","explain":"items() отдаёт сразу ключ и значение."},{"type":"code","q":"Телефонная книга","task":"Напиши <code>phone(book, name)</code>: вернуть номер из словаря book по имени, а если имени нет — строку <code>Нет такого</code>.","starter":"def phone(book, name):\n    pass\n","tests":[{"expr":"phone({'Ира': '123'}, 'Ира')","expect":"'123'"},{"expr":"phone({}, 'Коля')","expect":"'Нет такого'"}],"hint":"<code>book.get(name, \"Нет такого\")</code>","solution":"def phone(book, name):\n    return book.get(name, \"Нет такого\")","explain":"get с запасным значением — без всяких if."},{"type":"code","q":"Сколько разных","task":"Напиши <code>unique_count(lst)</code>: сколько разных элементов в списке.","starter":"def unique_count(lst):\n    pass\n","tests":[{"expr":"unique_count([1, 1, 2])","expect":"2"},{"expr":"unique_count([])","expect":"0"},{"expr":"unique_count(['a', 'b', 'a', 'c'])","expect":"3"}],"hint":"Множество убирает повторы: <code>len(set(lst))</code>.","solution":"def unique_count(lst):\n    return len(set(lst))","explain":"set — самый быстрый способ убрать повторы."}]},{"id":"p7b","title":"Практика: коллекции посложнее","emoji":"🗂️","intro":"Общие элементы, самая частая буква, группировка — задачи из реальных программ.","questions":[{"type":"code","q":"Общее","task":"Напиши <code>common(a, b)</code>: отсортированный список элементов, которые есть в обоих списках (без повторов).","starter":"def common(a, b):\n    pass\n","tests":[{"expr":"common([1, 2, 3], [2, 3, 4])","expect":"[2, 3]"},{"expr":"common([1], [2])","expect":"[]"},{"expr":"common([5, 5, 1], [5])","expect":"[5]"}],"hint":"Пересечение множеств: <code>sorted(set(a) &amp; set(b))</code>.","solution":"def common(a, b):\n    return sorted(set(a) & set(b))","explain":"Операции над множествами экономят кучу кода."},{"type":"code","q":"Самая частая буква","task":"Напиши <code>most_common(s)</code>: вернуть символ, который встречается чаще всего. Если таких несколько — тот, что встретился раньше.","starter":"def most_common(s):\n    pass\n","tests":[{"expr":"most_common(\"аабббв\")","expect":"'б'"},{"expr":"most_common(\"ааб\")","expect":"'а'"},{"expr":"most_common(\"абба\")","expect":"'а'"}],"hint":"Сначала подсчитай буквы словарём, потом пройди по строке и найди букву с наибольшим счётом (строго больше — чтобы осталась первая).","solution":"def most_common(s):\n    counts = {}\n    for ch in s:\n        counts[ch] = counts.get(ch, 0) + 1\n    best = s[0]\n    for ch in s:\n        if counts[ch] > counts[best]:\n            best = ch\n    return best","explain":"Два прохода: посчитать, потом выбрать."},{"type":"code","q":"Группировка по длине","task":"Напиши <code>group_by_len(words)</code>: словарь «длина → список слов такой длины» (в исходном порядке).","starter":"def group_by_len(words):\n    pass\n","tests":[{"expr":"group_by_len([\"кот\", \"ёж\", \"пёс\"])","expect":"{3: ['кот', 'пёс'], 2: ['ёж']}"},{"expr":"group_by_len([])","expect":"{}"}],"hint":"Если длины ещё нет в словаре — создай пустой список, потом append.","solution":"def group_by_len(words):\n    groups = {}\n    for w in words:\n        n = len(w)\n        if n not in groups:\n            groups[n] = []\n        groups[n].append(w)\n    return groups","explain":"Значением словаря может быть список — очень удобно."},{"type":"code","q":"Сложить словари","task":"Напиши <code>merge(d1, d2)</code>: новый словарь со всеми ключами; если ключ есть в обоих — значения складываются.","starter":"def merge(d1, d2):\n    pass\n","tests":[{"expr":"merge({'a': 1}, {'a': 2, 'b': 3})","expect":"{'a': 3, 'b': 3}"},{"expr":"merge({}, {'x': 5})","expect":"{'x': 5}"}],"hint":"Скопируй d1 (<code>dict(d1)</code>) и добавь значения из d2 через get.","solution":"def merge(d1, d2):\n    result = dict(d1)\n    for k, v in d2.items():\n        result[k] = result.get(k, 0) + v\n    return result","explain":"dict(d1) — копия, чтобы не испортить исходный словарь."}]}]},{"id":"u8","title":"Раздел 8. Ошибки и их обработка","lessons":[{"id":"l34","title":"Виды ошибок","emoji":"🚨","intro":"Python называет ошибки по имени: <code>SyntaxError</code> — код записан неправильно, <code>NameError</code> — нет такой переменной, <code>TypeError</code> — не тот тип, <code>ValueError</code> — не то значение, <code>ZeroDivisionError</code> — деление на 0.","questions":[{"type":"choice","q":"Какая ошибка будет?","code":"print(10 / 0)","err":"ZeroDivisionError","options":["ZeroDivisionError","NameError","TypeError","Ошибки не будет"],"explain":"На ноль делить нельзя."},{"type":"choice","q":"Какая ошибка будет?","code":"name = \"Яр\"\nprint(nmae)","err":"NameError","options":["NameError","SyntaxError","ValueError","Ошибки не будет"],"explain":"Опечатка: nmae вместо name. Такой переменной нет."},{"type":"choice","q":"Какая ошибка будет?","code":"print(\"5\" + 5)","err":"TypeError","options":["TypeError","ValueError","NameError","Выведет 10"],"explain":"Строку и число складывать нельзя — разные типы."},{"type":"choice","q":"Какая ошибка будет?","code":"x = int(\"пять\")","err":"ValueError","options":["ValueError","TypeError","ZeroDivisionError","x станет 5"],"explain":"int умеет переводить только цифры, а «пять» — нет."},{"type":"choice","q":"Какая ошибка будет?","code":"a = [1]\nprint(a[5])","err":"IndexError","options":["IndexError","KeyError","NameError","Выведет None"],"explain":"Элемента с индексом 5 нет."},{"type":"input","q":"Как называется ошибка деления на ноль?","answers":["ZeroDivisionError"],"explain":"Zero — ноль, Division — деление."}]},{"id":"l35","title":"try и except","emoji":"🛡️","intro":"Чтобы программа не падала, опасный код кладут в <code>try:</code>, а что делать при ошибке — в <code>except:</code>. Блок <code>finally:</code> выполняется всегда.","questions":[{"type":"output","q":"Что выведет код?","code":"try:\n    print(1 / 0)\nexcept ZeroDivisionError:\n    print(\"На ноль делить нельзя\")","options":["На ноль делить нельзя","Ошибку и остановку","0","Ничего"],"explain":"Ошибку поймали — программа не упала."},{"type":"output","q":"Что выведет код?","code":"try:\n    x = int(\"12\")\n    print(x + 1)\nexcept ValueError:\n    print(\"Не число\")","options":["13","Не число","121","Ошибку"],"explain":"Ошибки не было, except не сработал."},{"type":"output","q":"Что выведет код?","code":"try:\n    x = int(\"abc\")\nexcept ValueError:\n    x = 0\nprint(x)","options":["0","abc","Ошибку","None"],"explain":"int упал, в except поставили запасное значение 0."},{"type":"output","q":"Внимательно! Что выведет код?","code":"try:\n    print(\"A\")\n    print(1 / 0)\n    print(\"B\")\nexcept:\n    print(\"C\")","out":"A\nC","options":["A, потом C","A, B, C","Только C","A, потом B"],"explain":"До ошибки A напечаталось, B — уже нет: сразу прыгнули в except."},{"type":"output","q":"Что выведет код?","code":"try:\n    print(\"ok\")\nexcept:\n    print(\"ошибка\")\nfinally:\n    print(\"конец\")","out":"ok\nконец","options":["ok, потом конец","ok","ошибка, потом конец","конец"],"explain":"Ошибки не было, но finally выполняется в любом случае."},{"type":"input","q":"Какое слово ловит ошибку после try?","answers":["except"],"explain":"except — «кроме», «на случай ошибки»."}]},{"id":"l36","title":"Свои ошибки и проверки","emoji":"🧯","intro":"<code>raise</code> вызывает ошибку самому — например, если значение неправильное. <code>except ValueError as e</code> позволяет прочитать текст ошибки.","questions":[{"type":"output","q":"Что выведет код?","code":"def check(age):\n    if age < 0:\n        raise ValueError(\"Возраст не может быть меньше 0\")\n    return age\ntry:\n    check(-1)\nexcept ValueError as e:\n    print(e)","options":["Возраст не может быть меньше 0","-1","ValueError","Ничего"],"explain":"raise создал ошибку, а print(e) показал её текст."},{"type":"choice","q":"Что делает raise?","options":["Сам вызывает ошибку","Исправляет ошибку","Повторяет код","Выходит из цикла"],"explain":"Так функция сообщает: «так нельзя!»"},{"type":"output","q":"Что выведет код?","code":"def safe_div(a, b):\n    if b == 0:\n        return None\n    return a / b\nprint(safe_div(4, 0))","options":["None","0","Ошибку","inf"],"explain":"Проверили заранее и вернули None вместо ошибки."},{"type":"output","q":"pass — «ничего не делать». Что выведет код?","code":"nums = [\"1\", \"x\", \"3\"]\ntotal = 0\nfor n in nums:\n    try:\n        total += int(n)\n    except ValueError:\n        pass\nprint(total)","options":["4","13","Ошибку","0"],"explain":"«x» пропустили, сложили 1 и 3."},{"type":"output","q":"type() показывает тип. Что выведет код?","code":"print(type(5).__name__, type(\"5\").__name__)","options":["int str","str int","int int","5 5"],"explain":"int — целое число, str — строка."},{"type":"input","q":"Что выведет код? Напиши ответ.","code":"print(isinstance(3.5, float))","answers":["True"],"explain":"float — дробное число. 3.5 — float."}]},{"id":"p8a","title":"Практика: ловим ошибки","emoji":"💻","intro":"Пишем программы, которые не падают от неправильных данных.","questions":[{"type":"code","q":"Безопасное число","task":"Напиши <code>safe_int(s)</code>: вернуть число из строки, а если строка не число — вернуть 0.","starter":"def safe_int(s):\n    pass\n","tests":[{"expr":"safe_int(\"12\")","expect":"12"},{"expr":"safe_int(\"abc\")","expect":"0"},{"expr":"safe_int(\"-5\")","expect":"-5"}],"hint":"<code>try: return int(s)</code> / <code>except ValueError: return 0</code>","solution":"def safe_int(s):\n    try:\n        return int(s)\n    except ValueError:\n        return 0","explain":"try/except превращает падение программы в обычный ответ."},{"type":"code","q":"Безопасное деление","task":"Напиши <code>safe_div(a, b)</code>: вернуть a / b, а при делении на ноль — None.","starter":"def safe_div(a, b):\n    pass\n","tests":[{"expr":"safe_div(6, 3)","expect":"2.0"},{"expr":"safe_div(1, 0)","expect":"None"}],"hint":"Ловим <code>ZeroDivisionError</code>.","solution":"def safe_div(a, b):\n    try:\n        return a / b\n    except ZeroDivisionError:\n        return None","explain":"None — «ничего», хороший ответ, когда результата нет."},{"type":"code","q":"Безопасный индекс","task":"Напиши <code>get_item(lst, i)</code>: вернуть элемент lst[i], а если такого индекса нет — строку <code>Нет элемента</code>.","starter":"def get_item(lst, i):\n    pass\n","tests":[{"expr":"get_item([1, 2], 1)","expect":"2"},{"expr":"get_item([1, 2], 5)","expect":"'Нет элемента'"},{"expr":"get_item([], 0)","expect":"'Нет элемента'"}],"hint":"Ловим <code>IndexError</code>.","solution":"def get_item(lst, i):\n    try:\n        return lst[i]\n    except IndexError:\n        return \"Нет элемента\"","explain":"Каждой ошибке — свой except."}]},{"id":"p8b","title":"Практика: надёжные программы","emoji":"🛡️","intro":"Обрабатываем «грязные» данные и пустые списки.","questions":[{"type":"code","q":"Только числа","task":"Напиши <code>parse_numbers(text)</code>: из строки со словами вернуть список чисел, пропуская всё, что не число.","starter":"def parse_numbers(text):\n    pass\n","tests":[{"expr":"parse_numbers(\"1 a 2 b 3\")","expect":"[1, 2, 3]"},{"expr":"parse_numbers(\"кот\")","expect":"[]"},{"expr":"parse_numbers(\"-4 5\")","expect":"[-4, 5]"}],"hint":"Для каждого слова <code>try: result.append(int(w))</code>, <code>except ValueError: pass</code>.","solution":"def parse_numbers(text):\n    result = []\n    for w in text.split():\n        try:\n            result.append(int(w))\n        except ValueError:\n            pass\n    return result","explain":"pass — «ничего не делать»: просто пропускаем плохое слово."},{"type":"code","q":"Квадрат или ошибка","task":"Программа читает строку. Если это целое число — вывести его квадрат, иначе вывести <code>Это не число</code>.","starter":"s = input()\n","tests":[{"stdin":"5","out":"25"},{"stdin":"abc","out":"Это не число"},{"stdin":"-3","out":"9"}],"hint":"try: n = int(s) и print(n * n); except ValueError: print(...)","solution":"s = input()\ntry:\n    n = int(s)\n    print(n * n)\nexcept ValueError:\n    print(\"Это не число\")","explain":"Так пишут программы, которые не боятся ошибок пользователя."},{"type":"code","q":"Среднее без ошибок","task":"Напиши <code>average(lst)</code>: среднее арифметическое, а для пустого списка — 0.","starter":"def average(lst):\n    pass\n","tests":[{"expr":"average([])","expect":"0"},{"expr":"average([2, 4])","expect":"3.0"},{"expr":"average([5])","expect":"5.0"}],"hint":"Проверь <code>if not lst: return 0</code> перед делением.","solution":"def average(lst):\n    if not lst:\n        return 0\n    return sum(lst) / len(lst)","explain":"Пустой список — False. Проверка заранее — тоже способ избежать ошибки."}]}]},{"id":"u9","title":"Раздел 9. Модули","lessons":[{"id":"l37","title":"Модуль math","emoji":"📐","intro":"Модуль — готовый набор функций. Подключаем: <code>import math</code>, используем: <code>math.sqrt(16)</code>. Или так: <code>from math import sqrt</code>.","questions":[{"type":"output","q":"sqrt — квадратный корень. Что выведет код?","code":"import math\nprint(math.sqrt(16))","options":["4.0","4","256","8.0"],"explain":"sqrt всегда возвращает дробное число."},{"type":"output","q":"Что выведет код?","code":"import math\nprint(math.pi > 3)","options":["True","False","3.14","Ошибку"],"explain":"π ≈ 3,14159 — больше трёх."},{"type":"output","q":"floor — вниз, ceil — вверх. Что выведет код?","code":"import math\nprint(math.floor(3.7), math.ceil(3.2))","options":["3 4","4 3","3 3","4 4"],"explain":"floor(3.7) = 3, ceil(3.2) = 4."},{"type":"output","q":"Что выведет код?","code":"print(round(2.567, 1))","options":["2.6","2.5","3","2.57"],"explain":"round(число, 1) — округлить до одного знака."},{"type":"output","q":"Что выведет код?","code":"print(abs(-7))","options":["7","-7","0","Ошибку"],"explain":"abs — модуль числа, без минуса."},{"type":"input","q":"Что выведет код? Напиши ответ.","code":"from math import sqrt\nprint(sqrt(9))","answers":["3.0"],"explain":"Корень из 9 — 3.0."}]},{"id":"l38","title":"Случайность: random","emoji":"🎲","intro":"<code>random.randint(1, 6)</code> — случайное целое от 1 до 6 (включительно). <code>random.choice(список)</code> — случайный элемент. Так делают игры!","questions":[{"type":"choice","q":"Что делает random.randint(1, 6)?","options":["Даёт случайное целое от 1 до 6 включительно","Всегда даёт 6","Даёт дробное число","Выдаёт ошибку"],"explain":"Как бросок кубика."},{"type":"choice","q":"Что делает random.choice([\"кот\", \"пёс\"])?","options":["Выбирает случайный элемент списка","Сортирует список","Удаляет элемент","Всегда возвращает «кот»"],"explain":"choice — «выбор»."},{"type":"output","q":"Что выведет код?","code":"import random\nx = random.randint(5, 5)\nprint(x)","options":["5","Случайное число","10","Ошибку"],"explain":"Если начало и конец одинаковые, выбирать не из чего — всегда 5."},{"type":"output","q":"Что выведет код?","code":"import random\nprint(random.choice([\"только я\"]))","options":["только я","Случайное слово","['только я']","Ошибку"],"explain":"В списке один элемент — его и выбрали."},{"type":"choice","q":"Как подключить модуль random?","options":["import random","include random","using random","random()"],"explain":"В Python модули подключают словом import."},{"type":"input","q":"Какое слово подключает модуль?","answers":["import"],"explain":"import — «импортировать»."}]},{"id":"l39","title":"Проект: угадай число","emoji":"🎯","intro":"Собираем всё вместе! Игра: компьютер загадывает число, человек угадывает. Нужны: <code>random</code>, <code>input</code>, <code>int</code>, условия и цикл.","questions":[{"type":"choice","q":"Что делает эта программа?","code":"import random\nsecret = random.randint(1, 10)\nguess = int(input(\"Угадай: \"))\nif guess == secret:\n    print(\"Угадал!\")\nelse:\n    print(\"Не угадал, это было\", secret)","norun":true,"options":["Загадывает число от 1 до 10 и проверяет догадку","Считает сумму чисел","Печатает все числа от 1 до 10","Ничего не делает"],"explain":"Это и есть простая игра «Угадай число»."},{"type":"choice","q":"Зачем в игре int(input())?","options":["input() даёт строку, а сравнивать нужно числа","Чтобы было быстрее","Без int программа не запустится","Чтобы число было случайным"],"explain":"«5» (строка) не равно 5 (числу)."},{"type":"bug","q":"Почему здесь «Да» никогда не напечатается?","code":"guess = input(\"Число: \")\nif guess == 5:\n    print(\"Да\")","norun":true,"noError":true,"options":["Строка \"5\" не равна числу 5 — нужен int()","Нет else","Нельзя сравнивать с 5","Напечатается"],"explain":"Это логическая ошибка: программа не падает, но работает неправильно."},{"type":"output","q":"Считаем попытки. Что выведет код?","code":"tries = 0\nfor guess in [3, 7, 5]:\n    tries += 1\n    if guess == 5:\n        break\nprint(tries)","options":["3","2","5","1"],"explain":"Угадали с третьей попытки."},{"type":"output","q":"Подсказки «больше/меньше». Что выведет код?","code":"secret = 4\nfor g in [1, 4]:\n    if g < secret:\n        print(\"Больше\")\n    elif g > secret:\n        print(\"Меньше\")\n    else:\n        print(\"Угадал\")","out":"Больше\nУгадал","options":["Больше, потом Угадал","Меньше, потом Угадал","Угадал","Больше"],"explain":"1 < 4 — подсказка «Больше», потом 4 — угадал."},{"type":"input","q":"Что выведет код? Напиши ответ.","code":"secret = 7\nguess = 7\nprint(guess == secret)","answers":["True"],"explain":"Числа равны."}]},{"id":"p9a","title":"Практика: модули","emoji":"💻","intro":"Подключаем math, random и datetime — и решаем задачи в пару строк.","questions":[{"type":"code","q":"Гипотенуза","task":"Напиши <code>hyp(a, b)</code>: длина гипотенузы прямоугольного треугольника с катетами a и b (√(a² + b²)).","starter":"import math\n\ndef hyp(a, b):\n    pass\n","tests":[{"expr":"hyp(3, 4)","expect":"5.0"},{"expr":"hyp(6, 8)","expect":"10.0"}],"hint":"<code>math.sqrt(a * a + b * b)</code>","solution":"import math\n\ndef hyp(a, b):\n    return math.sqrt(a * a + b * b)","explain":"Теорема Пифагора в одну строку."},{"type":"code","q":"Площадь круга","task":"Напиши <code>circle_area(r)</code>: площадь круга π·r², округлённая до 2 знаков.","starter":"import math\n\ndef circle_area(r):\n    pass\n","tests":[{"expr":"circle_area(1)","expect":"3.14"},{"expr":"circle_area(2)","expect":"12.57"},{"expr":"circle_area(0)","expect":"0.0"}],"hint":"<code>round(math.pi * r * r, 2)</code>","solution":"import math\n\ndef circle_area(r):\n    return round(math.pi * r * r, 2)","explain":"math.pi — точное значение π."},{"type":"code","q":"Кубик","task":"Напиши <code>roll()</code>: случайное целое от 1 до 6 включительно.","starter":"import random\n\ndef roll():\n    pass\n","tests":[{"expr":"all(1 <= roll() <= 6 for _ in range(200))","expect":"True"},{"expr":"len({roll() for _ in range(500)}) == 6","expect":"True"}],"hint":"<code>random.randint(1, 6)</code>","solution":"import random\n\ndef roll():\n    return random.randint(1, 6)","explain":"Тест бросил кубик сотни раз: все значения от 1 до 6, и все шесть встречаются."},{"type":"code","q":"Сколько дней","task":"Напиши <code>days_between(y1, m1, d1, y2, m2, d2)</code>: сколько дней между двумя датами.","starter":"from datetime import date\n\ndef days_between(y1, m1, d1, y2, m2, d2):\n    pass\n","tests":[{"expr":"days_between(2026, 1, 1, 2026, 1, 31)","expect":"30"},{"expr":"days_between(2026, 1, 1, 2027, 1, 1)","expect":"365"}],"hint":"Разность дат: <code>(date(y2, m2, d2) - date(y1, m1, d1)).days</code>","solution":"from datetime import date\n\ndef days_between(y1, m1, d1, y2, m2, d2):\n    return (date(y2, m2, d2) - date(y1, m1, d1)).days","explain":"datetime сам знает, сколько дней в каждом месяце и високосные годы."}]},{"id":"p9b","title":"Проект: игра «Угадай число»","emoji":"🎯","intro":"Собираем настоящую игру! Здесь загаданное число приходит первой строкой ввода — так Питоша может проверить игру тестами.","questions":[{"type":"code","q":"Угадай число","task":"Первая строка ввода — загаданное число, дальше — попытки игрока (каждая на своей строке). На каждую попытку выводи <code>Больше</code> или <code>Меньше</code>, а при угадывании — <code>Угадал! Попыток: N</code> и заканчивай игру.","starter":"secret = int(input())\n","tests":[{"stdin":"5\n3\n8\n5","out":"Больше\nМеньше\nУгадал! Попыток: 3"},{"stdin":"1\n1","out":"Угадал! Попыток: 1"},{"stdin":"50\n25\n75\n50","out":"Больше\nМеньше\nУгадал! Попыток: 3"}],"hint":"<code>while True:</code> читай guess, увеличивай счётчик; если угадал — печатай и <code>break</code>.","solution":"secret = int(input())\ntries = 0\nwhile True:\n    guess = int(input())\n    tries += 1\n    if guess < secret:\n        print(\"Больше\")\n    elif guess > secret:\n        print(\"Меньше\")\n    else:\n        print(f\"Угадал! Попыток: {tries}\")\n        break","explain":"В настоящей игре secret = random.randint(1, 100) — и можно играть!"},{"type":"code","q":"Лучшая стратегия","task":"Напиши <code>max_tries(n)</code>: сколько попыток в худшем случае нужно, чтобы угадать число от 1 до n, если каждый раз делить диапазон пополам. Например, для 100 — 7.","starter":"def max_tries(n):\n    pass\n","tests":[{"expr":"max_tries(100)","expect":"7"},{"expr":"max_tries(1)","expect":"1"},{"expr":"max_tries(1000)","expect":"10"},{"expr":"max_tries(8)","expect":"4"}],"hint":"Считай, сколько раз нужно удвоить 1, чтобы покрыть n: пока <code>2 ** k - 1 < n</code>, увеличивай k.","solution":"def max_tries(n):\n    k = 0\n    while 2 ** k - 1 < n:\n        k += 1\n    return k","explain":"Это «двоичный поиск» — один из самых важных алгоритмов в программировании."},{"type":"code","q":"Камень-ножницы-бумага","task":"Напиши <code>winner(a, b)</code> для двух ходов (\"камень\", \"ножницы\", \"бумага\"): вернуть <code>1</code>, если выиграл первый, <code>2</code> — если второй, <code>0</code> — ничья.","starter":"def winner(a, b):\n    pass\n","tests":[{"expr":"winner(\"камень\", \"ножницы\")","expect":"1"},{"expr":"winner(\"камень\", \"бумага\")","expect":"2"},{"expr":"winner(\"бумага\", \"бумага\")","expect":"0"},{"expr":"winner(\"ножницы\", \"бумага\")","expect":"1"}],"hint":"Словарь «что побеждает что»: <code>beats = {\"камень\": \"ножницы\", ...}</code>.","solution":"def winner(a, b):\n    beats = {\"камень\": \"ножницы\", \"ножницы\": \"бумага\", \"бумага\": \"камень\"}\n    if a == b:\n        return 0\n    if beats[a] == b:\n        return 1\n    return 2","explain":"Словарь вместо кучи if — так пишут профи."}]}]},{"id":"u10","title":"Раздел 10. Классы и объекты","lessons":[{"id":"l40","title":"Классы и объекты","emoji":"🏗️","intro":"Класс — чертёж, объект — вещь по чертежу. <code>class Dog:</code> создаёт класс, <code>Dog()</code> — объект. <code>__init__</code> запускается при создании объекта, <code>self</code> — сам объект.","questions":[{"type":"output","q":"Что выведет код?","code":"class Cat:\n    pass\nc = Cat()\nprint(type(c).__name__)","options":["Cat","c","object","Ошибку"],"explain":"c — объект класса Cat."},{"type":"output","q":"Что выведет код?","code":"class Dog:\n    def __init__(self, name):\n        self.name = name\nd = Dog(\"Шарик\")\nprint(d.name)","options":["Шарик","name","Dog","Ошибку"],"explain":"__init__ сохранил имя в объекте: self.name = name."},{"type":"choice","q":"Что такое self?","options":["Сам объект, с которым работает метод","Название класса","Встроенная функция print","Ошибка в коде"],"explain":"Через self объект хранит свои данные."},{"type":"output","q":"Что выведет код?","code":"class Counter:\n    def __init__(self):\n        self.n = 0\nc = Counter()\nc.n += 5\nprint(c.n)","options":["5","0","n","Ошибку"],"explain":"У объекта поле n было 0, стало 5."},{"type":"choice","q":"Когда вызывается __init__?","options":["Автоматически при создании объекта","Только если вызвать вручную","При удалении объекта","Никогда"],"explain":"Dog(\"Шарик\") сразу запускает __init__."},{"type":"input","q":"Какое слово создаёт класс?","answers":["class"],"explain":"class — «класс»."}]},{"id":"l41","title":"Методы","emoji":"⚙️","intro":"Метод — функция внутри класса. Первый параметр всегда <code>self</code>. Вызываем через точку: <code>hero.hit(30)</code>.","questions":[{"type":"output","q":"Что выведет код?","code":"class Cat:\n    def say(self):\n        return \"Мяу\"\nprint(Cat().say())","options":["Мяу","say","Cat","Ошибку"],"explain":"Создали кота и вызвали его метод."},{"type":"output","q":"Игровой герой. Что выведет код?","code":"class Hero:\n    def __init__(self):\n        self.hp = 100\n    def hit(self, dmg):\n        self.hp -= dmg\nh = Hero()\nh.hit(30)\nh.hit(20)\nprint(h.hp)","options":["50","100","70","80"],"explain":"100 − 30 − 20 = 50."},{"type":"output","q":"Что выведет код?","code":"class P:\n    def __init__(self, name):\n        self.name = name\n    def hello(self):\n        print(\"Я\", self.name)\nP(\"Питоша\").hello()","options":["Я Питоша","Я name","Питоша","Ошибку"],"explain":"Метод достаёт имя из self."},{"type":"bug","q":"Почему код упадёт?","code":"class A:\n    def f():\n        return 1\nprint(A().f())","options":["Забыли self в методе","Нельзя возвращать 1","Класс без __init__","Он не упадёт"],"explain":"Python сам передаёт объект в метод — нужен параметр self."},{"type":"output","q":"Что выведет код?","code":"class Box:\n    def __init__(self):\n        self.items = []\n    def add(self, x):\n        self.items.append(x)\nb = Box()\nb.add(1)\nb.add(2)\nprint(len(b.items))","options":["2","1","0","[1, 2]"],"explain":"В коробку положили две вещи."},{"type":"input","q":"Что выведет код? Напиши ответ.","code":"class C:\n    def __init__(self, v):\n        self.v = v\nprint(C(7).v * 2)","answers":["14"],"explain":"v = 7, умножили на 2."}]},{"id":"l42","title":"Наследование","emoji":"🧬","intro":"<code>class Cat(Animal):</code> — кот получает всё от Animal и может что-то поменять. <code>super()</code> — обратиться к родителю.","questions":[{"type":"output","q":"Что выведет код?","code":"class Animal:\n    def sound(self):\n        return \"...\"\nclass Cat(Animal):\n    def sound(self):\n        return \"Мяу\"\nprint(Cat().sound())","options":["Мяу","...","Мяу...","Ошибку"],"explain":"Кот переопределил метод родителя."},{"type":"output","q":"Что выведет код?","code":"class Animal:\n    def eat(self):\n        return \"Ем\"\nclass Dog(Animal):\n    pass\nprint(Dog().eat())","options":["Ем","Ничего","Dog","Ошибку"],"explain":"Метода eat у Dog нет, он достался от Animal."},{"type":"choice","q":"Что значит class Cat(Animal)?","options":["Cat наследует всё от Animal","Animal наследует от Cat","Cat и Animal — одно и то же","Cat внутри Animal"],"explain":"Родитель в скобках."},{"type":"output","q":"Что выведет код?","code":"class A:\n    def __init__(self):\n        self.x = 1\nclass B(A):\n    def __init__(self):\n        super().__init__()\n        self.y = 2\nb = B()\nprint(b.x + b.y)","options":["3","2","1","Ошибку"],"explain":"super().__init__() запустил __init__ родителя, и x тоже появился."},{"type":"output","q":"Что выведет код?","code":"class A:\n    pass\nclass B(A):\n    pass\nprint(isinstance(B(), A))","options":["True","False","B","Ошибку"],"explain":"Объект B — это тоже A, потому что B наследует от A."},{"type":"input","q":"Как обратиться к родительскому классу внутри метода?","answers":["super()","super"],"explain":"super() — «родитель»."}]},{"id":"l43","title":"Особые методы","emoji":"✨","intro":"Методы с двумя подчёркиваниями — особые. <code>__str__</code> — как объект печатается, <code>__add__</code> — что делает <code>+</code>. Переменная класса общая для всех объектов.","questions":[{"type":"output","q":"Что выведет код?","code":"class P:\n    def __str__(self):\n        return \"Питоша\"\nprint(P())","options":["Питоша","P","<__main__.P object>","Ошибку"],"explain":"print использует __str__."},{"type":"output","q":"Что выведет код?","code":"class Pt:\n    def __init__(self, x, y):\n        self.x = x\n        self.y = y\n    def __str__(self):\n        return f\"({self.x}, {self.y})\"\nprint(Pt(1, 2))","options":["(1, 2)","Pt","1 2","(x, y)"],"explain":"__str__ вернул красивую строку."},{"type":"output","q":"Переменная класса — общая. Что выведет код?","code":"class Pet:\n    count = 0\n    def __init__(self):\n        Pet.count += 1\nPet()\nPet()\nprint(Pet.count)","options":["2","1","0","Ошибку"],"explain":"Каждый новый Pet увеличил общий счётчик."},{"type":"choice","q":"Зачем нужен __str__?","options":["Чтобы объект красиво печатался через print","Чтобы создать объект","Чтобы удалить объект","Для сложения"],"explain":"Без него print покажет что-то вроде <__main__.P object at 0x…>."},{"type":"output","q":"Что выведет код?","code":"class Num:\n    def __init__(self, v):\n        self.v = v\n    def __add__(self, other):\n        return Num(self.v + other.v)\nprint((Num(2) + Num(3)).v)","options":["5","23","Ошибку","Num"],"explain":"Мы научили объекты складываться через __add__."},{"type":"input","q":"Что выведет код? Напиши ответ.","code":"class A:\n    name = \"класс\"\nprint(A.name)","answers":["класс"],"explain":"К переменной класса можно обратиться через имя класса."}]},{"id":"p10a","title":"Практика: классы","emoji":"💻","intro":"Создаём свои классы. Питоша создаст объекты и проверит, как они работают.","questions":[{"type":"code","q":"Собака","task":"Создай класс <code>Dog</code>: в <code>__init__</code> сохрани имя, метод <code>bark()</code> возвращает <code>ИМЯ: Гав!</code>","starter":"class Dog:\n    pass\n","tests":[{"expr":"Dog(\"Шарик\").bark()","expect":"'Шарик: Гав!'"},{"expr":"Dog(\"Бобик\").bark()","expect":"'Бобик: Гав!'"}],"hint":"<code>def __init__(self, name): self.name = name</code> и <code>return f\"{self.name}: Гав!\"</code>","solution":"class Dog:\n    def __init__(self, name):\n        self.name = name\n\n    def bark(self):\n        return f\"{self.name}: Гав!\"","explain":"self.name — имя хранится внутри объекта."},{"type":"code","q":"Счётчик","task":"Создай класс <code>Counter</code>: поле <code>value</code> начинается с 0, метод <code>inc()</code> увеличивает его на 1.","starter":"class Counter:\n    pass\n","tests":[{"expr":"(lambda c: (c.inc(), c.inc(), c.value)[2])(Counter())","expect":"2"},{"expr":"Counter().value","expect":"0"}],"hint":"В __init__: <code>self.value = 0</code>, в inc: <code>self.value += 1</code>.","solution":"class Counter:\n    def __init__(self):\n        self.value = 0\n\n    def inc(self):\n        self.value += 1","explain":"Объект помнит своё состояние между вызовами методов."},{"type":"code","q":"Прямоугольник","task":"Создай класс <code>Rectangle(w, h)</code> с методами <code>area()</code> и <code>perimeter()</code>.","starter":"class Rectangle:\n    pass\n","tests":[{"expr":"Rectangle(3, 4).area()","expect":"12"},{"expr":"Rectangle(3, 4).perimeter()","expect":"14"},{"expr":"Rectangle(1, 1).area()","expect":"1"}],"hint":"Площадь — w * h, периметр — 2 * (w + h).","solution":"class Rectangle:\n    def __init__(self, w, h):\n        self.w = w\n        self.h = h\n\n    def area(self):\n        return self.w * self.h\n\n    def perimeter(self):\n        return 2 * (self.w + self.h)","explain":"Данные и действия над ними — в одном месте."}]},{"id":"p10b","title":"Практика: банк и животные","emoji":"🏦","intro":"Чуть сложнее: банковский счёт с проверками и наследование.","questions":[{"type":"code","q":"Банковский счёт","task":"Класс <code>BankAccount</code>: <code>balance</code> начинается с 0, <code>deposit(x)</code> добавляет деньги, <code>withdraw(x)</code> снимает и возвращает True, а если денег не хватает — ничего не снимает и возвращает False.","starter":"class BankAccount:\n    pass\n","tests":[{"expr":"(lambda a: (a.deposit(100), a.withdraw(30), a.balance)[2])(BankAccount())","expect":"70"},{"expr":"(lambda a: (a.withdraw(10), a.balance))(BankAccount())","expect":"(False, 0)"},{"expr":"(lambda a: (a.deposit(50), a.withdraw(50)))(BankAccount())[1]","expect":"True"}],"hint":"В withdraw: <code>if x > self.balance: return False</code>, иначе вычти и верни True.","solution":"class BankAccount:\n    def __init__(self):\n        self.balance = 0\n\n    def deposit(self, x):\n        self.balance += x\n\n    def withdraw(self, x):\n        if x > self.balance:\n            return False\n        self.balance -= x\n        return True","explain":"Объект сам следит, чтобы баланс не ушёл в минус."},{"type":"code","q":"Животные","task":"Класс <code>Animal</code> с методом <code>speak()</code> → <code>...</code>. Наследники: <code>Cat</code> → <code>Мяу</code>, <code>Dog</code> → <code>Гав</code>.","starter":"class Animal:\n    def speak(self):\n        return \"...\"\n","tests":[{"expr":"[a.speak() for a in [Cat(), Dog(), Animal()]]","expect":"['Мяу', 'Гав', '...']"},{"expr":"isinstance(Cat(), Animal)","expect":"True"}],"hint":"<code>class Cat(Animal):</code> и переопредели speak.","solution":"class Animal:\n    def speak(self):\n        return \"...\"\n\n\nclass Cat(Animal):\n    def speak(self):\n        return \"Мяу\"\n\n\nclass Dog(Animal):\n    def speak(self):\n        return \"Гав\"","explain":"Один и тот же вызов speak() — разное поведение. Это называется полиморфизм."},{"type":"code","q":"Точка","task":"Класс <code>Point(x, y)</code>, который печатается как <code>(x, y)</code>.","starter":"class Point:\n    pass\n","tests":[{"expr":"str(Point(1, 2))","expect":"'(1, 2)'"},{"expr":"str(Point(-5, 0))","expect":"'(-5, 0)'"}],"hint":"Метод <code>__str__</code> возвращает <code>f\"({self.x}, {self.y})\"</code>.","solution":"class Point:\n    def __init__(self, x, y):\n        self.x = x\n        self.y = y\n\n    def __str__(self):\n        return f\"({self.x}, {self.y})\"","explain":"__str__ отвечает за то, как объект выглядит в print и str()."}]}]},{"id":"u11","title":"Раздел 11. Python как профи","lessons":[{"id":"l44","title":"Генераторы списков","emoji":"⚡","intro":"Список в одну строку: <code>[x * 2 for x in range(4)]</code>. С условием: <code>[x for x in a if x &gt; 0]</code>. Так же можно сделать словарь.","questions":[{"type":"output","q":"Что выведет код?","code":"print([x * 2 for x in range(4)])","options":["[0, 2, 4, 6]","[2, 4, 6, 8]","[0, 1, 2, 3]","8"],"explain":"Каждое x из 0, 1, 2, 3 умножили на 2."},{"type":"output","q":"Что выведет код?","code":"print([x for x in range(10) if x % 3 == 0])","options":["[0, 3, 6, 9]","[3, 6, 9]","[0, 3, 6]","[1, 4, 7]"],"explain":"Оставили только числа, которые делятся на 3 (0 тоже делится)."},{"type":"output","q":"Что выведет код?","code":"words = [\"кот\", \"пёс\"]\nprint([w.upper() for w in words])","options":["['КОТ', 'ПЁС']","['кот', 'пёс']","КОТ ПЁС","Ошибку"],"explain":"Ко всем словам применили upper()."},{"type":"output","q":"Генератор словаря. Что выведет код?","code":"print({x: x * x for x in range(3)})","options":["{0: 0, 1: 1, 2: 4}","{0, 1, 4}","[0, 1, 4]","{1: 1, 2: 4}"],"explain":"Ключ — число, значение — его квадрат."},{"type":"output","q":"Что выведет код?","code":"print(len([c for c in \"питоша\" if c in \"аио\"]))","options":["3","6","2","4"],"explain":"Нашлись буквы и, о, а."},{"type":"input","q":"Что выведет код? Напиши ответ.","code":"print([i for i in range(3)])","answers":["[0, 1, 2]"],"explain":"Самый простой генератор."}]},{"id":"l45","title":"enumerate и zip","emoji":"🤝","intro":"<code>enumerate</code> даёт номер и элемент сразу. <code>zip</code> идёт по двум спискам одновременно, парами.","questions":[{"type":"output","q":"Что выведет код?","code":"for i, ch in enumerate(\"ab\"):\n    print(i, ch)","out":"0 a\n1 b","options":["0 a и 1 b на двух строках","a b","1 a и 2 b","0 1"],"explain":"enumerate нумерует с нуля."},{"type":"output","q":"Что выведет код?","code":"names = [\"Ира\", \"Коля\"]\nages = [40, 42]\nfor n, a in zip(names, ages):\n    print(n, a)","out":"Ира 40\nКоля 42","options":["Ира 40 и Коля 42 на двух строках","Ира Коля 40 42","Ира 42 и Коля 40","Ошибку"],"explain":"zip сложил элементы попарно."},{"type":"output","q":"Что выведет код?","code":"print(list(enumerate([\"x\"], start=1)))","options":["[(1, 'x')]","[(0, 'x')]","['x']","[1]"],"explain":"start=1 — нумерация с единицы."},{"type":"output","q":"Что выведет код?","code":"print(dict(zip([\"a\", \"b\"], [1, 2])))","options":["{'a': 1, 'b': 2}","[('a', 1), ('b', 2)]","{'a', 'b', 1, 2}","Ошибку"],"explain":"Из пар получился словарь."},{"type":"output","q":"zip останавливается на коротком. Что выведет код?","code":"print(list(zip([1, 2, 3], \"ab\")))","options":["[(1, 'a'), (2, 'b')]","[(1, 'a'), (2, 'b'), (3, '')]","Ошибку","[1, 2, 3, 'a', 'b']"],"explain":"Для 3 пары не нашлось — zip её отбросил."},{"type":"input","q":"Что выведет код? Напиши ответ.","code":"for i, x in enumerate([5, 6]):\n    pass\nprint(i)","answers":["1"],"explain":"После цикла i осталось последним номером — 1."}]},{"id":"l46","title":"sorted, lambda и key","emoji":"🗃️","intro":"<code>lambda x: x + 1</code> — короткая функция в одну строку. <code>key</code> говорит sorted/max, по чему сравнивать: <code>sorted(a, key=len)</code> — по длине.","questions":[{"type":"output","q":"Что выведет код?","code":"print(sorted([3, 1, 2], reverse=True))","options":["[3, 2, 1]","[1, 2, 3]","[3, 1, 2]","[2, 1, 3]"],"explain":"reverse=True — по убыванию."},{"type":"output","q":"Что выведет код?","code":"print(sorted([\"бб\", \"а\", \"ввв\"], key=len))","options":["['а', 'бб', 'ввв']","['ввв', 'бб', 'а']","['бб', 'а', 'ввв']","[1, 2, 3]"],"explain":"Сортировка по длине слова."},{"type":"output","q":"Что выведет код?","code":"f = lambda x: x + 10\nprint(f(5))","options":["15","510","5","Ошибку"],"explain":"lambda — та же функция, только короче."},{"type":"output","q":"Кто самый младший? Что выведет код?","code":"people = [(\"Ира\", 40), (\"Яр\", 12)]\nprint(sorted(people, key=lambda p: p[1])[0][0])","options":["Яр","Ира","12","Ошибку"],"explain":"Сортировали по возрасту, первым оказался Яр."},{"type":"output","q":"Что выведет код?","code":"print(max([\"кот\", \"слон\", \"ёж\"], key=len))","options":["слон","ёж","кот","4"],"explain":"Самое длинное слово."},{"type":"input","q":"map применяет функцию ко всем элементам. Что выведет код?","code":"print(list(map(str, [1, 2])))","answers":["['1', '2']"],"explain":"Числа превратились в строки."}]},{"id":"l47","title":"Итоговый экзамен","emoji":"🏆","intro":"Финал! Здесь всё вперемешку: функции, циклы, словари, списки. Если пройдёшь без ошибок — ты знаешь основы Python. Дальше — пиши свои программы и ботов!","questions":[{"type":"output","q":"Знаменитая задача FizzBuzz. Что выведет код?","code":"def fizz(n):\n    if n % 15 == 0:\n        return \"FizzBuzz\"\n    if n % 3 == 0:\n        return \"Fizz\"\n    if n % 5 == 0:\n        return \"Buzz\"\n    return str(n)\nprint(fizz(9), fizz(10), fizz(30))","options":["Fizz Buzz FizzBuzz","Fizz Fizz Fizz","9 10 30","Buzz Fizz FizzBuzz"],"explain":"9 делится на 3, 10 — на 5, 30 — на 15."},{"type":"output","q":"Счётчик слов. Что выведет код?","code":"text = \"кот пёс кот\"\nwords = {}\nfor w in text.split():\n    words[w] = words.get(w, 0) + 1\nprint(words[\"кот\"])","options":["2","1","3","кот"],"explain":"«кот» встречается дважды."},{"type":"output","q":"Простые числа. Что выведет код?","code":"def is_prime(n):\n    if n < 2:\n        return False\n    for d in range(2, n):\n        if n % d == 0:\n            return False\n    return True\nprint([n for n in range(10) if is_prime(n)])","options":["[2, 3, 5, 7]","[1, 2, 3, 5, 7]","[2, 3, 5, 7, 9]","[3, 5, 7]"],"explain":"Простые делятся только на 1 и на себя."},{"type":"output","q":"Хитрый вопрос! Что выведет код?","code":"a = [1, 2, 3]\nb = a\nb.append(4)\nprint(a)","options":["[1, 2, 3, 4]","[1, 2, 3]","[4]","Ошибку"],"explain":"b = a не копирует список: a и b — один и тот же список. Копия — a.copy()."},{"type":"output","q":"Что выведет код?","code":"print(sum(range(1, 101)))","options":["5050","5000","100","10100"],"explain":"Сумма чисел от 1 до 100 — знаменитые 5050."},{"type":"input","q":"Последний вопрос! Что выведет код?","code":"s = \"Python\"\nprint(s[::2])","answers":["Pto"],"explain":"Шаг 2 — каждая вторая буква: P, t, o. Поздравляю — ты прошёл весь курс! 🎉"}]},{"id":"p11a","title":"Практика: как профи","emoji":"💻","intro":"Генераторы списков, zip, enumerate и sorted с key — пишем коротко и красиво.","questions":[{"type":"code","q":"Квадраты","task":"Напиши <code>squares(n)</code>: список квадратов чисел от 1 до n — в одну строку!","starter":"def squares(n):\n    pass\n","tests":[{"expr":"squares(4)","expect":"[1, 4, 9, 16]"},{"expr":"squares(0)","expect":"[]"}],"hint":"<code>return [i * i for i in range(1, n + 1)]</code>","solution":"def squares(n):\n    return [i * i for i in range(1, n + 1)]","explain":"Генератор списка — коротко и быстро."},{"type":"code","q":"По длине","task":"Напиши <code>by_length(words)</code>: слова, отсортированные по длине, а одинаковые по длине — по алфавиту.","starter":"def by_length(words):\n    pass\n","tests":[{"expr":"by_length([\"ccc\", \"a\", \"bb\", \"aa\"])","expect":"['a', 'aa', 'bb', 'ccc']"},{"expr":"by_length([])","expect":"[]"}],"hint":"key может вернуть пару: <code>sorted(words, key=lambda w: (len(w), w))</code>","solution":"def by_length(words):\n    return sorted(words, key=lambda w: (len(w), w))","explain":"Кортеж в key — сортировка сразу по двум признакам."},{"type":"code","q":"Пары","task":"Напиши <code>pairs(names, ages)</code>: словарь «имя → возраст» из двух списков.","starter":"def pairs(names, ages):\n    pass\n","tests":[{"expr":"pairs([\"Ира\", \"Коля\"], [40, 42])","expect":"{'Ира': 40, 'Коля': 42}"}],"hint":"<code>dict(zip(names, ages))</code>","solution":"def pairs(names, ages):\n    return dict(zip(names, ages))","explain":"zip + dict — две строчки работы в одну."},{"type":"code","q":"Нумерация","task":"Напиши <code>numbered(items)</code>: список строк вида <code>1. первый</code>, <code>2. второй</code>…","starter":"def numbered(items):\n    pass\n","tests":[{"expr":"numbered([\"a\", \"b\"])","expect":"['1. a', '2. b']"},{"expr":"numbered([])","expect":"[]"}],"hint":"<code>[f\"{i}. {x}\" for i, x in enumerate(items, 1)]</code>","solution":"def numbered(items):\n    return [f\"{i}. {x}\" for i, x in enumerate(items, 1)]","explain":"enumerate(…, 1) — нумерация с единицы."}]},{"id":"p11b","title":"Финальный практикум","emoji":"🏆","intro":"Последние задачи курса. Решишь их сам — значит, основы Python у тебя в кармане!","questions":[{"type":"code","q":"FizzBuzz","task":"Прочитай n и выведи числа от 1 до n, но вместо кратных 3 — <code>Fizz</code>, кратных 5 — <code>Buzz</code>, кратных и 3, и 5 — <code>FizzBuzz</code>.","starter":"n = int(input())\n","tests":[{"stdin":"5","out":"1\n2\nFizz\n4\nBuzz"},{"stdin":"15","out":"1\n2\nFizz\n4\nBuzz\nFizz\n7\n8\nFizz\nBuzz\n11\nFizz\n13\n14\nFizzBuzz"}],"hint":"Сначала проверяй <code>i % 15 == 0</code>, потом 3, потом 5.","solution":"n = int(input())\nfor i in range(1, n + 1):\n    if i % 15 == 0:\n        print(\"FizzBuzz\")\n    elif i % 3 == 0:\n        print(\"Fizz\")\n    elif i % 5 == 0:\n        print(\"Buzz\")\n    else:\n        print(i)","explain":"Знаменитая задача с собеседований — теперь ты её решил!"},{"type":"code","q":"Расплющить","task":"Напиши <code>flatten(lst)</code>: из списка списков сделать один список.","starter":"def flatten(lst):\n    pass\n","tests":[{"expr":"flatten([[1, 2], [3], []])","expect":"[1, 2, 3]"},{"expr":"flatten([])","expect":"[]"}],"hint":"Двойной генератор: <code>[x for sub in lst for x in sub]</code>","solution":"def flatten(lst):\n    return [x for sub in lst for x in sub]","explain":"В генераторе можно писать два for подряд."},{"type":"code","q":"Топ-3","task":"Напиши <code>top3(scores)</code>: по словарю «имя → очки» вернуть список трёх имён с наибольшими очками (по убыванию).","starter":"def top3(scores):\n    pass\n","tests":[{"expr":"top3({'a': 5, 'b': 9, 'c': 7, 'd': 1})","expect":"['b', 'c', 'a']"},{"expr":"top3({'x': 1, 'y': 2})","expect":"['y', 'x']"}],"hint":"<code>sorted(scores, key=lambda k: scores[k], reverse=True)[:3]</code>","solution":"def top3(scores):\n    return sorted(scores, key=lambda k: scores[k], reverse=True)[:3]","explain":"Ровно так считается рейтинг в Питоше!"},{"type":"code","q":"Анаграммы","task":"Напиши <code>is_anagram(a, b)</code>: True, если слова состоят из одних и тех же букв (без учёта регистра). Например, «Кот» и «ток».","starter":"def is_anagram(a, b):\n    pass\n","tests":[{"expr":"is_anagram(\"Кот\", \"ток\")","expect":"True"},{"expr":"is_anagram(\"кот\", \"кит\")","expect":"False"},{"expr":"is_anagram(\"листок\", \"слиток\")","expect":"True"}],"hint":"Отсортируй буквы: <code>sorted(a.lower()) == sorted(b.lower())</code>","solution":"def is_anagram(a, b):\n    return sorted(a.lower()) == sorted(b.lower())","explain":"Поздравляю — ты прошёл весь курс основ Python! 🎉"}]}]}]}.units;
  const LESSONS = UNITS.flatMap(u => u.lessons.map(l => ({ ...l, unit: u.id })));
  const lessonById = id => LESSONS.find(l => l.id === id) || null;
  const lessonIndex = id => LESSONS.findIndex(l => l.id === id);
  const api = { UNITS, LESSONS, lessonById, lessonIndex };
  if (typeof module !== 'undefined' && module.exports) module.exports = api; else root.COURSE = api;
})(typeof self !== 'undefined' ? self : this);
